interface ClusterRamp8 {
  c0: Rgb;
  c1: Rgb;
  c2: Rgb;
  c3: Rgb;
  c4: Rgb;
  c5: Rgb;
  c6: Rgb;
  c7: Rgb;
}

interface TrimRamp5 {
  t0: Rgb;
  t1: Rgb;
  t2: Rgb;
  t3: Rgb;
  t4: Rgb;
}

interface StudioPalette {
  body: ClusterRamp8;
  trim: TrimRamp5;
  metal: TrimRamp5;
  bone: TrimRamp5;
  crimson: TrimRamp5;
  eyeGlow: Rgb;
  eyeSocket: Rgb;
  white: Rgb;
}

function makeRamp8(pri: Rgb, sec: Rgb, specTint: Rgb = [218, 244, 253]): ClusterRamp8 {
  return {
    c0: darken(sec, 0.58),
    c1: darken(sec, 0.28),
    c2: sec,
    c3: mixRgb(sec, pri, 0.32),
    c4: mixRgb(sec, pri, 0.68),
    c5: pri,
    c6: mixRgb(pri, specTint, 0.52),
    c7: mixRgb(pri, specTint, 0.88),
  };
}

function makeTrim5(acc: Rgb, rustShift: Rgb = [180, 74, 35]): TrimRamp5 {
  return {
    t0: mixRgb(rustShift, darken(acc, 0.5), 0.5),
    t1: mixRgb(rustShift, acc, 0.32),
    t2: mixRgb(rustShift, acc, 0.62),
    t3: acc,
    t4: lighten(acc, 0.48),
  };
}

function buildStudioPalette(p: FactionPalette): StudioPalette {
  const pri = hexToRgb(p.primary);
  const sec = hexToRgb(p.secondary);
  const acc = hexToRgb(p.accent);
  return {
    body: makeRamp8(pri, sec),
    trim: makeTrim5(acc),
    metal: {
      t0: [33, 34, 38],
      t1: [48, 52, 62],
      t2: [113, 112, 115],
      t3: [154, 154, 156],
      t4: [215, 224, 235],
    },
    bone: {
      t0: [64, 52, 42],
      t1: [108, 92, 76],
      t2: [162, 144, 122],
      t3: [216, 202, 180],
      t4: [248, 244, 232],
    },
    crimson: {
      t0: [62, 14, 26],
      t1: [112, 22, 38],
      t2: [168, 34, 52],
      t3: [224, 56, 72],
      t4: [255, 164, 168],
    },
    eyeGlow: [37, 255, 225],
    eyeSocket: [9, 29, 50],
    white: [248, 253, 255],
  };
}

function dir8Vector(dir: SpriteDir8): { dx: number; dy: number } {
  switch (dir) {
    case 'S':
      return { dx: 0, dy: 1 };
    case 'SE':
      return { dx: 0.72, dy: 0.72 };
    case 'E':
      return { dx: 1, dy: 0 };
    case 'NE':
      return { dx: 0.72, dy: -0.72 };
    case 'N':
      return { dx: 0, dy: -1 };
    case 'NW':
      return { dx: -0.72, dy: -0.72 };
    case 'W':
      return { dx: -1, dy: 0 };
    case 'SW':
      return { dx: -0.72, dy: 0.72 };
  }
}

class SculptCanvas32 {
  public readonly size = SPRITE_SIZE;
  public readonly fxSize = SPRITE_FX_SIZE;
  /** 유닛 몸 레이어 (스프라이트 시트에 들어가는 32x32 픽셀) */
  public readonly body = new Uint8ClampedArray(SPRITE_SIZE * SPRITE_SIZE * 4);
  /** 이펙트 레이어 (48x48, 사방 8px 확장 여백): 총구 섬광·참격·저격선이 잘리지 않으며 몸 중심점을 고정한다 */
  public readonly fx = new Uint8ClampedArray(SPRITE_FX_SIZE * SPRITE_FX_SIZE * 4);
  private target: Uint8ClampedArray = this.body;
  private isFxTarget = false;

  public get data(): Uint8ClampedArray {
    return this.target;
  }

  /** 이후 그리기를 48x48 이펙트 레이어로 보낸다 (좌표계는 32x32 기준 -8..39까지 허용) */
  public fxBegin(): void {
    this.target = this.fx;
    this.isFxTarget = true;
  }

  public fxEnd(): void {
    this.target = this.body;
    this.isFxTarget = false;
  }

  public inBounds(x: number, y: number): boolean {
    return x >= 0 && x < this.size && y >= 0 && y < this.size;
  }

  public isOpaque(x: number, y: number): boolean {
    if (!this.inBounds(x, y)) {
      return false;
    }
    return this.body[(Math.round(y) * this.size + Math.round(x)) * 4 + 3] > 0;
  }

  public px(x: number, y: number, c: Rgb): void {
    if (this.isFxTarget) {
      const ix = Math.round(x) + SPRITE_FX_PAD;
      const iy = Math.round(y) + SPRITE_FX_PAD;
      if (ix < 0 || ix >= this.fxSize || iy < 0 || iy >= this.fxSize) {
        return;
      }
      const i = (iy * this.fxSize + ix) * 4;
      this.fx[i] = c[0];
      this.fx[i + 1] = c[1];
      this.fx[i + 2] = c[2];
      this.fx[i + 3] = 255;
      return;
    }
    const ix = Math.round(x);
    const iy = Math.round(y);
    if (!this.inBounds(ix, iy)) {
      return;
    }
    const i = (iy * this.size + ix) * 4;
    this.body[i] = c[0];
    this.body[i + 1] = c[1];
    this.body[i + 2] = c[2];
    this.body[i + 3] = 255;
  }

  public clearPx(x: number, y: number): void {
    if (this.isFxTarget) {
      const ix = Math.round(x) + SPRITE_FX_PAD;
      const iy = Math.round(y) + SPRITE_FX_PAD;
      if (ix < 0 || ix >= this.fxSize || iy < 0 || iy >= this.fxSize) {
        return;
      }
      const i = (iy * this.fxSize + ix) * 4;
      this.fx[i] = 0;
      this.fx[i + 1] = 0;
      this.fx[i + 2] = 0;
      this.fx[i + 3] = 0;
      return;
    }
    const ix = Math.round(x);
    const iy = Math.round(y);
    if (!this.inBounds(ix, iy)) {
      return;
    }
    const i = (iy * this.size + ix) * 4;
    this.body[i] = 0;
    this.body[i + 1] = 0;
    this.body[i + 2] = 0;
    this.body[i + 3] = 0;
  }

  public symPx(x: number, y: number, c: Rgb): void {
    this.px(x, y, c);
    this.px(31 - x, y, c);
  }

  public rect(x: number, y: number, w: number, h: number, c: Rgb): void {
    for (let dy = 0; dy < h; dy += 1) {
      for (let dx = 0; dx < w; dx += 1) {
        this.px(x + dx, y + dy, c);
      }
    }
  }

  public symRect(x: number, y: number, w: number, h: number, c: Rgb): void {
    this.rect(x, y, w, h, c);
    this.rect(32 - x - w, y, w, h, c);
  }

  public hLine(x1: number, x2: number, y: number, c: Rgb): void {
    const a = Math.min(x1, x2);
    const b = Math.max(x1, x2);
    for (let x = a; x <= b; x += 1) {
      this.px(x, y, c);
    }
  }

  public vLine(x: number, y1: number, y2: number, c: Rgb): void {
    const a = Math.min(y1, y2);
    const b = Math.max(y1, y2);
    for (let y = a; y <= b; y += 1) {
      this.px(x, y, c);
    }
  }

  public symVLine(x: number, y1: number, y2: number, c: Rgb): void {
    this.vLine(x, y1, y2, c);
    this.vLine(31 - x, y1, y2, c);
  }

  public partDome(
    cx: number,
    cy: number,
    rx: number,
    ry: number,
    ramp: ClusterRamp8,
    opts?: {
      trim?: TrimRamp5;
      trimBottom?: boolean;
      trimInnerSide?: 'LEFT' | 'RIGHT' | 'BOTH';
      specOffsetX?: number;
      specOffsetY?: number;
    }
  ): void {
    const x0 = Math.floor(cx - rx - 1);
    const x1 = Math.ceil(cx + rx + 1);
    const y0 = Math.floor(cy - ry - 1);
    const y1 = Math.ceil(cy + ry + 1);

    const inside = (x: number, y: number): boolean => {
      const nx = (x - cx) / Math.max(0.5, rx);
      const ny = (y - cy) / Math.max(0.5, ry);
      return nx * nx + ny * ny <= 1.0;
    };

    const sx = opts?.specOffsetX ?? -0.22;
    const sy = opts?.specOffsetY ?? -0.32;

    for (let y = y0; y <= y1; y += 1) {
      for (let x = x0; x <= x1; x += 1) {
        if (!inside(x, y)) {
          if (
            inside(x - 1, y) ||
            inside(x + 1, y) ||
            inside(x, y - 1) ||
            inside(x, y + 1)
          ) {
            this.px(x, y, OUTLINE_RGB);
          }
          continue;
        }

        const nx = (x - cx) / Math.max(0.5, rx);
        const ny = (y - cy) / Math.max(0.5, ry);

        if (opts?.trim) {
          const tr = opts.trim;
          const isBottomRim = opts.trimBottom && !inside(x, y + 1);
          const isLeftRim =
            (opts.trimInnerSide === 'LEFT' || opts.trimInnerSide === 'BOTH') &&
            !inside(x - 1, y) &&
            Math.abs(ny) < 0.72;
          const isRightRim =
            (opts.trimInnerSide === 'RIGHT' || opts.trimInnerSide === 'BOTH') &&
            !inside(x + 1, y) &&
            Math.abs(ny) < 0.72;

          if (isLeftRim || isRightRim) {
            const tc = ny < -0.2 ? tr.t4 : ny < 0.25 ? tr.t3 : tr.t1;
            this.px(x, y, tc);
            continue;
          }
          if (isBottomRim) {
            const tc = Math.abs(nx) < 0.35 ? tr.t2 : tr.t0;
            this.px(x, y, tc);
            continue;
          }
        }

        const dSpec = Math.hypot(nx - sx, ny - sy);
        let col: Rgb;
        if (dSpec < 0.34) {
          col = ramp.c7;
        } else if (dSpec < 0.56) {
          col = ramp.c6;
        } else if (dSpec < 0.85) {
          col = ramp.c5;
        } else if (dSpec < 1.1) {
          col = ramp.c4;
        } else if (ny < 0.45) {
          col = ramp.c3;
        } else if (ny < 0.75) {
          col = ramp.c2;
        } else {
          col = ramp.c1;
        }
        this.px(x, y, col);
      }
    }
  }

  public symPartDome(
    leftCx: number,
    cy: number,
    rx: number,
    ry: number,
    ramp: ClusterRamp8,
    opts?: {
      trim?: TrimRamp5;
      trimBottom?: boolean;
      trimInner?: boolean;
    }
  ): void {
    this.partDome(leftCx, cy, rx, ry, ramp, {
      trim: opts?.trim,
      trimBottom: opts?.trimBottom,
      trimInnerSide: opts?.trimInner ? 'RIGHT' : undefined,
      specOffsetX: 0.1,
      specOffsetY: -0.28,
    });
    this.partDome(31 - leftCx, cy, rx, ry, ramp, {
      trim: opts?.trim,
      trimBottom: opts?.trimBottom,
      trimInnerSide: opts?.trimInner ? 'LEFT' : undefined,
      specOffsetX: -0.1,
      specOffsetY: -0.28,
    });
  }

  public partCapsule(
    x0: number,
    y0: number,
    x1: number,
    y1: number,
    r: number,
    ramp: ClusterRamp8
  ): void {
    const minX = Math.floor(Math.min(x0, x1) - r - 1);
    const maxX = Math.ceil(Math.max(x0, x1) + r + 1);
    const minY = Math.floor(Math.min(y0, y1) - r - 1);
    const maxY = Math.ceil(Math.max(y0, y1) + r + 1);
    const vx = x1 - x0;
    const vy = y1 - y0;
    const len2 = vx * vx + vy * vy || 1;

    const distSq = (x: number, y: number): { d2: number; nx: number; ny: number } => {
      const t = Math.max(0, Math.min(1, ((x - x0) * vx + (y - y0) * vy) / len2));
      const px = x0 + vx * t;
      const py = y0 + vy * t;
      const dx = x - px;
      const dy = y - py;
      return {
        d2: dx * dx + dy * dy,
        nx: dx / Math.max(0.5, r),
        ny: dy / Math.max(0.5, r),
      };
    };

    const r2 = r * r;
    for (let y = minY; y <= maxY; y += 1) {
      for (let x = minX; x <= maxX; x += 1) {
        const cur = distSq(x, y);
        if (cur.d2 > r2) {
          if (
            distSq(x - 1, y).d2 <= r2 ||
            distSq(x + 1, y).d2 <= r2 ||
            distSq(x, y - 1).d2 <= r2 ||
            distSq(x, y + 1).d2 <= r2
          ) {
            this.px(x, y, OUTLINE_RGB);
          }
          continue;
        }
        const dSpec = Math.hypot(cur.nx + 0.2, cur.ny + 0.35);
        const col =
          dSpec < 0.42
            ? ramp.c7
            : dSpec < 0.72
              ? ramp.c5
              : dSpec < 1.05
                ? ramp.c3
                : ramp.c1;
        this.px(x, y, col);
      }
    }
  }

  public symPartCapsule(
    x0: number,
    y0: number,
    x1: number,
    y1: number,
    r: number,
    ramp: ClusterRamp8
  ): void {
    this.partCapsule(x0, y0, x1, y1, r, ramp);
    this.partCapsule(31 - x0, y0, 31 - x1, y1, r, ramp);
  }

  public sculptVisorFace(
    cy: number,
    body: ClusterRamp8,
    trim: TrimRamp5,
    eyeCol: Rgb,
    maskMode: 'RESPIRATOR' | 'TEMPLAR' | 'FANGS',
    xShift: number = 0
  ): void {
    const cxL = 15 + xShift;
    const cxR = 16 + xShift;
    this.px(cxL, cy - 3, trim.t3);
    this.px(cxR, cy - 3, trim.t3);
    this.px(cxL, cy - 2, trim.t4);
    this.px(cxR, cy - 2, trim.t4);
    this.px(cxL - 1, cy - 1, body.c6);
    this.px(cxL, cy - 1, body.c7);
    this.px(cxR, cy - 1, body.c7);
    this.px(cxR + 1, cy - 1, body.c6);

    for (const [ox, ex] of [
      [cxL - 3, cxL - 2],
      [cxR + 3, cxR + 2],
    ]) {
      this.px(ox, cy, OUTLINE_RGB);
      this.px(ex, cy - 1, OUTLINE_RGB);
      this.px(ex, cy, eyeCol);
      this.px(ex + (ex < cxL ? 1 : -1), cy, lighten(eyeCol, 0.55));
      this.px(ex, cy + 1, darken(eyeCol, 0.45));
      this.px(ox, cy + 1, OUTLINE_RGB);
    }
    this.px(cxL, cy, body.c4);
    this.px(cxR, cy, body.c4);
    this.px(cxL, cy + 1, body.c5);
    this.px(cxR, cy + 1, body.c5);

    if (maskMode === 'RESPIRATOR') {
      this.hLine(cxL - 2, cxR + 2, cy + 2, [113, 112, 115]);
      this.px(cxL, cy + 2, [210, 215, 222]);
      this.px(cxR, cy + 2, [154, 154, 156]);
      this.hLine(cxL - 1, cxR + 1, cy + 3, [113, 112, 115]);
      this.px(cxL - 2, cy + 3, OUTLINE_RGB);
      this.px(cxR + 2, cy + 3, OUTLINE_RGB);
    } else if (maskMode === 'TEMPLAR') {
      this.px(cxL, cy - 2, eyeCol);
      this.px(cxR, cy - 2, eyeCol);
      this.hLine(cxL - 1, cxR + 1, cy + 2, body.c6);
      this.hLine(cxL - 1, cxR + 1, cy + 3, trim.t4);
    } else {
      this.px(cxL - 3, cy + 2, [248, 244, 232]);
      this.px(cxR + 3, cy + 2, [248, 244, 232]);
      this.px(cxL - 2, cy + 2, OUTLINE_RGB);
      this.px(cxR + 2, cy + 2, OUTLINE_RGB);
      this.px(cxL - 1, cy + 2, [248, 244, 232]);
      this.px(cxR + 1, cy + 2, [248, 244, 232]);
      this.px(cxL, cy + 2, [112, 22, 38]);
      this.px(cxR, cy + 2, [112, 22, 38]);
      this.hLine(cxL - 1, cxR + 1, cy + 3, OUTLINE_RGB);
    }
  }

  public stampMuzzleBlast(
    cx: number,
    cy: number,
    dirX: number,
    dirY: number,
    f: number,
    theme: 'FIRE' | 'PLASMA' | 'GOLD' | 'ACID' | 'CYAN' | 'CRIMSON' = 'FIRE'
  ): void {
    const getThemeColors = (): { core: Rgb; bright: Rgb; mid: Rgb; outer: Rgb; smoke: Rgb } => {
      switch (theme) {
        case 'PLASMA':
          return {
            core: [255, 255, 255],
            bright: [224, 255, 255],
            mid: [110, 238, 255],
            outer: [255, 207, 74],
            smoke: [48, 86, 128],
          };
        case 'GOLD':
          return {
            core: [255, 255, 255],
            bright: [255, 248, 176],
            mid: [255, 207, 74],
            outer: [242, 140, 36],
            smoke: [78, 62, 48],
          };
        case 'ACID':
          return {
            core: [255, 255, 255],
            bright: [242, 255, 175],
            mid: [184, 238, 64],
            outer: [88, 168, 28],
            smoke: [42, 74, 24],
          };
        case 'CYAN':
          return {
            core: [255, 255, 255],
            bright: [215, 254, 255],
            mid: [95, 224, 255],
            outer: [32, 136, 204],
            smoke: [22, 64, 98],
          };
        case 'CRIMSON':
          return {
            core: [255, 255, 255],
            bright: [255, 224, 195],
            mid: [255, 96, 82],
            outer: [178, 28, 46],
            smoke: [68, 24, 32],
          };
        default:
          return {
            core: [255, 255, 255],
            bright: [252, 246, 132],
            mid: [252, 232, 86],
            outer: [235, 119, 36],
            smoke: [76, 56, 52],
          };
      }
    };

    const tc = getThemeColors();
    const mapColor = (ch: string): Rgb | null => {
      if (ch === '.' || (f % 2 === 1 && ch === 'Z')) {
        return null;
      }
      if (ch === '@' || ch === '^') {
        return f % 2 === 0 ? tc.core : tc.bright;
      }
      if (ch === '$' || ch === '#') {
        return f % 2 === 0 ? tc.bright : tc.mid;
      }
      if (ch === '!' || ch === '%') {
        return f % 2 === 0 ? tc.mid : tc.outer;
      }
      return tc.outer;
    };

    const prev = this.target;
    const prevFlag = this.isFxTarget;
    this.fxBegin();
    const targetAng = Math.atan2(dirY, dirX);
    const refAng = Math.PI / 4;
    const dAng = targetAng - refAng;
    const cosA = Math.cos(dAng);
    const sinA = Math.sin(dAng);
    const h = MUZZLE_FLASH_TEMPLATE_SE.length;
    const w = MUZZLE_FLASH_TEMPLATE_SE[0].length;

    for (let dy = -6; dy <= 6; dy += 1) {
      for (let dx = -6; dx <= 6; dx += 1) {
        const tx = Math.round(dx * cosA + dy * sinA + 4.5);
        const ty = Math.round(-dx * sinA + dy * cosA + 4.0);
        if (ty < 0 || ty >= h || tx < 0 || tx >= w) {
          continue;
        }
        const col = mapColor(MUZZLE_FLASH_TEMPLATE_SE[ty][tx]);
        if (col) {
          this.px(Math.round(cx + dx), Math.round(cy + dy), col);
        }
      }
    }

    const perpX = -dirY;
    const perpY = dirX;
    if (f % 2 === 0) {
      // Stage 1 (발사 순간): 전방 집중 예광 스파이크 (48x48 여백까지 뻗음) + 좌우 십자 머즐 브레이크 제트
      for (let s = 3; s <= 7; s += 1) {
        this.px(cx + dirX * s, cy + dirY * s, s <= 5 ? tc.core : tc.bright);
      }
      for (const side of [-1, 1]) {
        this.px(cx + dirX * 2 + perpX * side * 3, cy + dirY * 2 + perpY * side * 3, tc.bright);
        this.px(cx + dirX * 2 + perpX * side * 4, cy + dirY * 2 + perpY * side * 4, tc.mid);
      }
    } else {
      // Stage 2 (반동 순간): 전방 확산 잔열/연기 퍼프 + 옆으로 튀는 황동 탄피/스파크 픽셀
      for (const side of [-1, 1]) {
        const sx = cx + dirX * 5 + perpX * side * 3;
        const sy = cy + dirY * 5 + perpY * side * 3;
        this.px(sx, sy, tc.smoke);
        this.px(sx + dirX, sy + dirY, tc.outer);
      }
      this.px(cx + dirX * 7, cy + dirY * 7, tc.mid);
      this.px(cx + dirX * 8, cy + dirY * 8, tc.smoke);
      // 약실 방향 탄피/스파크 배출
      const shellX = cx - dirX * 3 + perpX * 4;
      const shellY = cy - dirY * 3 + perpY * 4 - 2;
      this.px(shellX, shellY, [255, 224, 120]);
      this.px(shellX - perpX, shellY + 1, [204, 152, 52]);
    }

    this.target = prev;
    this.isFxTarget = prevFlag;
  }

  /** 방패 분대 / 성벽 분대 전용: 타워 실드 전방 이중 충격파 판 + 파쇄 스파크 */
  public stampShieldBash(cx: number, cy: number, dirX: number, dirY: number, f: number, evolved = false): void {
    const prev = this.target;
    const prevFlag = this.isFxTarget;
    this.fxBegin();
    const perpX = -dirY;
    const perpY = dirX;
    const mainCol: Rgb = evolved ? [255, 207, 74] : [95, 224, 255];
    const subCol: Rgb = evolved ? [242, 140, 36] : [32, 136, 204];
    const coreCol: Rgb = [255, 255, 255];
    const push = f % 2 === 0 ? 0 : 2;

    for (let u = -6; u <= 6; u += 1) {
      const curve = Math.round((1 - (u / 6.5) ** 2) * 3.5) + push;
      const ax = cx + perpX * u + dirX * curve;
      const ay = cy + perpY * u + dirY * curve;
      this.px(ax, ay, Math.abs(u) <= 3 ? coreCol : mainCol);
      this.px(ax - dirX, ay - dirY, mainCol);
      if (f % 2 === 0 && Math.abs(u) <= 4) {
        this.px(ax + dirX, ay + dirY, subCol);
      }
    }
    // 전방 파쇄 스파크 3갈래
    for (const k of [-3, 0, 3]) {
      const sx = cx + perpX * k * 1.3 + dirX * (5 + push + (k === 0 ? 2 : 0));
      const sy = cy + perpY * k * 1.3 + dirY * (5 + push + (k === 0 ? 2 : 0));
      this.px(sx, sy, f % 2 === 0 ? coreCol : mainCol);
      if (f % 2 === 1) {
        this.px(sx + dirX, sy + dirY, subCol);
      }
    }
    this.target = prev;
    this.isFxTarget = prevFlag;
  }

  /** 수리 드론 / 보급 드론 전용: 나노 수리 파동 링 + 의무 십자(+) 도트 */
  public stampNanoHeal(cx: number, cy: number, dirX: number, dirY: number, f: number, evolved = false): void {
    const prev = this.target;
    const prevFlag = this.isFxTarget;
    this.fxBegin();
    const main: Rgb = evolved ? [255, 224, 112] : [92, 242, 156];
    const sub: Rgb = evolved ? [92, 242, 156] : [36, 176, 112];
    const white: Rgb = [255, 255, 255];

    const r = f % 2 === 0 ? 3 : 5;
    for (let k = 0; k < 8; k += 1) {
      const a = (k / 8) * Math.PI * 2;
      this.px(cx + Math.cos(a) * r, cy + Math.sin(a) * r, k % 2 === 0 ? main : sub);
    }
    // 미니 의무 십자(+) 2개
    const c1x = Math.round(cx + dirX * (3 + f * 2));
    const c1y = Math.round(cy + dirY * (3 + f * 2) - 2);
    for (const [ox, oy] of [[0, 0], [-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
      this.px(c1x + ox, c1y + oy, ox === 0 && oy === 0 ? white : main);
    }
    this.target = prev;
    this.isFxTarget = prevFlag;
  }

  /** 갈퀴충 · 껍질갑충 · 파쇄 여왕 전용: 3갈래 초승달 발톱 할퀴기 궤적 */
  public stampClawSlash(
    cx: number,
    cy: number,
    dirX: number,
    dirY: number,
    f: number,
    theme: 'ACID' | 'CRIMSON' | 'GOLD' = 'ACID'
  ): void {
    const prev = this.target;
    const prevFlag = this.isFxTarget;
    this.fxBegin();
    const perpX = -dirY;
    const perpY = dirX;
    const bright: Rgb =
      theme === 'CRIMSON' ? [255, 110, 96] : theme === 'GOLD' ? [255, 224, 112] : [192, 248, 72];
    const dark: Rgb =
      theme === 'CRIMSON' ? [168, 24, 42] : theme === 'GOLD' ? [196, 112, 24] : [74, 156, 24];
    const white: Rgb = [255, 255, 255];

    for (const lane of [-3.5, 0, 3.5]) {
      for (let s = -4; s <= 4; s += 1) {
        if (f % 2 === 1 && s < -1) continue;
        const arc = (1 - (s / 4.5) ** 2) * 3.5 + (f % 2 === 1 ? 1.5 : 0);
        const px = cx + perpX * (lane + s * 0.85) + dirX * (arc + (lane === 0 ? 1.5 : 0));
        const py = cy + perpY * (lane + s * 0.85) + dirY * (arc + (lane === 0 ? 1.5 : 0));
        const col = s >= 2 ? white : s >= -1 ? bright : dark;
        this.px(px, py, col);
      }
    }
    this.target = prev;
    this.isFxTarget = prevFlag;
  }

  /** 교단 수호기사(광휘검 초승달 검기) · 광선창병(관통 프리즘 창 찌르기 충격파) 전용 */
  public stampBladeArc(
    cx: number,
    cy: number,
    dirX: number,
    dirY: number,
    f: number,
    mode: 'SWORD' | 'LANCE' = 'SWORD'
  ): void {
    const prev = this.target;
    const prevFlag = this.isFxTarget;
    this.fxBegin();
    const perpX = -dirY;
    const perpY = dirX;
    const cyan: Rgb = [95, 224, 255];
    const deep: Rgb = [32, 136, 204];
    const gold: Rgb = [242, 208, 104];
    const white: Rgb = [255, 255, 255];

    if (mode === 'LANCE') {
      // 전방 관통 광선창 찌르기 + V자 음속 충격파 고리
      const reach = f % 2 === 0 ? 9 : 6;
      for (let s = -2; s <= reach; s += 1) {
        const px = cx + dirX * s;
        const py = cy + dirY * s;
        this.px(px, py, s >= reach - 2 ? white : cyan);
        if (s >= 0 && s <= 4) {
          this.px(px + perpX, py + perpY, s === 2 ? white : deep);
          this.px(px - perpX, py - perpY, s === 2 ? white : deep);
        }
      }
      for (const side of [-1, 1]) {
        for (let w = 1; w <= 3; w += 1) {
          this.px(cx + dirX * (2 - w) + perpX * side * (w + 1), cy + dirY * (2 - w) + perpY * side * (w + 1), w === 1 ? gold : cyan);
        }
      }
    } else {
      // 넓은 초승달 광휘 검기 호
      for (let u = -7; u <= 7; u += 1) {
        if (f % 2 === 1 && u < -3) continue;
        const curve = (1 - (u / 7.5) ** 2) * 5.0 + (f % 2 === 1 ? 1.5 : 0);
        const ax = cx + perpX * u + dirX * curve;
        const ay = cy + perpY * u + dirY * curve;
        this.px(ax + dirX, ay + dirY, Math.abs(u) <= 3 ? white : cyan);
        this.px(ax, ay, Math.abs(u) <= 4 ? cyan : deep);
        if (Math.abs(u) <= 5 && f % 2 === 0) {
          this.px(ax - dirX, ay - dirY, gold);
        }
      }
    }
    this.target = prev;
    this.isFxTarget = prevFlag;
  }

  /** 진드기 · 기어충 · 파쇄충 · 모체 · 분열충 · 갑각충 전용: 상하 이빨 맞물림(Bite Snap) + 타액 파편 */
  public stampBiteSnap(
    cx: number,
    cy: number,
    dirX: number,
    dirY: number,
    f: number,
    theme: 'CRIMSON' | 'ACID' = 'CRIMSON'
  ): void {
    const prev = this.target;
    const prevFlag = this.isFxTarget;
    this.fxBegin();
    const perpX = -dirY;
    const perpY = dirX;
    const bone: Rgb = [248, 244, 232];
    const boneShade: Rgb = [196, 180, 156];
    const blood: Rgb = theme === 'ACID' ? [184, 238, 64] : [236, 68, 72];
    const darkBlood: Rgb = theme === 'ACID' ? [78, 152, 24] : [156, 20, 36];
    const white: Rgb = [255, 255, 255];

    if (f % 2 === 0) {
      // Frame 0: 위아래 송곳니 턱이 양옆에서 안쪽으로 날카롭게 맞물림
      for (const side of [-1, 1]) {
        for (let t = 0; t <= 4; t += 1) {
          const jx = cx + perpX * side * (4 - t * 0.7) + dirX * (t * 0.9);
          const jy = cy + perpY * side * (4 - t * 0.7) + dirY * (t * 0.9);
          this.px(jx, jy, t >= 3 ? white : t >= 1 ? bone : boneShade);
        }
        // 안쪽 보조 송곳니
        this.px(cx + perpX * side * 2 + dirX * 2, cy + perpY * side * 2 + dirY * 2, bone);
      }
      this.px(cx + dirX * 3, cy + dirY * 3, blood);
    } else {
      // Frame 1: 맞물린 중심 크런치 십자 섬광 + 튀는 체액 방울
      this.px(cx + dirX * 2, cy + dirY * 2, white);
      for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
        this.px(cx + dirX * 2 + ox, cy + dirY * 2 + oy, blood);
      }
      for (const side of [-1, 1]) {
        this.px(cx + dirX * 5 + perpX * side * 3, cy + dirY * 5 + perpY * side * 3, blood);
        this.px(cx + dirX * 4 + perpX * side * 4, cy + dirY * 4 + perpY * side * 4, darkBlood);
      }
    }
    this.target = prev;
    this.isFxTarget = prevFlag;
  }

  public finalizeOutline(): void {
    const snap = new Uint8ClampedArray(this.data);
    const isOp = (x: number, y: number): boolean =>
      this.inBounds(x, y) && snap[(y * this.size + x) * 4 + 3] > 0;

    for (let y = 0; y < this.size; y += 1) {
      for (let x = 0; x < this.size; x += 1) {
        if (isOp(x, y)) {
          continue;
        }
        if (isOp(x - 1, y) || isOp(x + 1, y) || isOp(x, y - 1) || isOp(x, y + 1)) {
          this.px(x, y, OUTLINE_RGB);
        }
      }
    }
  }
}

/**
 * IMG_2485.png / IMG_2486.png 의 156색 인덱스를 진영 팔레트로 매핑하는 테이블 생성기.
 * - 기본 노바 기동군 팔레트(#4f7fb8)일 때는 IMG_2485.png / IMG_2486.png 원본 RGB를 100% 그대로 반환한다.
 */
function buildRef8DirColorLut(
  palette: FactionPalette,
  customEye?: Rgb
): Rgb[] {
  const isDefaultIronclad = palette.primary.toLowerCase() === '#4f7fb8' && !customEye;
  const sp = buildStudioPalette(palette);
  const eye = customEye ?? sp.eyeGlow;

  return REF_8DIR_PALETTE.map((rgb, idx): Rgb => {
    if (idx === 0) {
      return [0, 0, 0];
    }
    const [r, g, b] = rgb;
    if (r === OUTLINE_RGB[0] && g === OUTLINE_RGB[1] && b === OUTLINE_RGB[2]) {
      return OUTLINE_RGB;
    }
    if (isDefaultIronclad) {
      return [r, g, b];
    }
    // 청록 발광 바이저 안구
    if (g > 205 && b > 195 && r < 95) {
      return eye;
    }
    // 안구 그늘 소켓
    if (r < 20 && g > 35 && b > 50 && b < 110) {
      return darken(eye, 0.55);
    }
    // 금장/구리 트림 및 총구 화염 계열
    if (r > b + 32) {
      if (r > 248 && g > 240 && b > 170) {
        return sp.white;
      }
      return r > 238
        ? sp.trim.t4
        : r > 215
          ? sp.trim.t3
          : r > 190
            ? sp.trim.t2
            : r > 165
              ? sp.trim.t1
              : sp.trim.t0;
    }
    // 무채색 금속 마스크/건틀릿/소총 계열
    if (Math.abs(r - g) <= 13 && Math.abs(g - b) <= 15) {
      return r > 140 ? sp.metal.t3 : r > 95 ? sp.metal.t2 : sp.metal.t0;
    }
    // 주 장갑 8단계 클러스터 매핑
    const lum = (r * 0.299 + g * 0.587 + b * 0.114) / 255;
    return lum > 0.86
      ? sp.body.c7
      : lum > 0.72
        ? sp.body.c6
        : lum > 0.52
          ? sp.body.c5
          : lum > 0.4
            ? sp.body.c4
            : lum > 0.3
              ? sp.body.c3
              : lum > 0.22
                ? sp.body.c2
                : lum > 0.14
                  ? sp.body.c1
                  : sp.body.c0;
  });
}

/**
 * IMG_2485.png (8방향 IDLE 시트) 및 IMG_2486.png (8방향 ATTACK 사격 시트)에서
 * 해당 방향(S=0, SE=1, E=2, NE=3, N=4, NW=5, W=6, SW=7)의 32x32 슬라이스를 스탬핑한다.
 */
/** 원본 ATTACK 시트의 방향별 총구 영역 [x0, y0, x1, y1]: 이 안의 불꽃색 픽셀 = 총구 화염 (이펙트 레이어로 분리) */
const REF_ATK_MUZZLE_BOX: Readonly<Record<SpriteDir8, readonly [number, number, number, number] | null>> = {
  S: [22, 21, 31, 31],
  SE: [26, 19, 31, 31],
  E: [25, 8, 31, 19],
  NE: [24, 0, 31, 6],
  N: [16, 0, 26, 3],
  NW: null,
  W: [0, 7, 5, 18],
  SW: [0, 19, 5, 31],
};

function isRefFlameColor(idx: number): boolean {
  const [r, g, b] = REF_8DIR_PALETTE[idx];
  return (r >= 150 && r > g && g >= b && r - b >= 60) || (r > 240 && g > 240 && b > 200);
}

function isEvolvedPalette(palette: FactionPalette): boolean {
  const pri = palette.primary.toLowerCase();
  const acc = palette.accent.toLowerCase();
  return pri === '#d8dde6' || acc === '#ffe070' || acc === '#ffcf4a';
}

/** 방향별 소총 총구 끝 좌표 (32x32 기준): 확장 예광·탄피·NW 섬광 스탬핑 기준점 */
const RIFLE_MUZZLE_TIP: Readonly<Record<SpriteDir8, readonly [number, number]>> = {
  S: [25, 25],
  SE: [29, 23],
  E: [29, 14],
  NE: [27, 3],
  N: [21, 1],
  NW: [5, 3],
  W: [2, 13],
  SW: [3, 23],
};

/**
 * IMG_2485 / IMG_2486 8방향 원본 시트를 진영 팔레트로 찍는다 (정지 포즈).
 * 걷기·숨쉬기·반동 모션은 공용 애니메이터(planFrame)가 모든 아키타입에 동일하게 적용한다.
 */
function stamp8DirSheet(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim,
  yOffset: number = 0,
  customEye?: Rgb,
  useAttackRifleSheet: boolean = true
): void {
  const dirIdx = Math.max(0, ALL_DIRS_8.indexOf(dir));
  const sliceX = dirIdx * 32;
  const useAtk = anim === 'ATTACK' && useAttackRifleSheet;
  const sheet = useAtk ? REF_ATK_8DIR_SHEET : REF_IDLE_8DIR_SHEET;
  const lut = buildRef8DirColorLut(palette, customEye);
  const f = frame % 2;

  for (let y = 0; y < 32; y += 1) {
    const rowBase = y * 256 + sliceX;
    for (let x = 0; x < 32; x += 1) {
      const palIdx = sheet[rowBase + x];
      if (palIdx === 0) {
        continue;
      }
      const box = useAtk ? REF_ATK_MUZZLE_BOX[dir] : null;
      if (box && x >= box[0] && x <= box[2] && y >= box[1] && y <= box[3] && isRefFlameColor(palIdx)) {
        // Frame 0(발사)에서는 원본 총구 화염 전체, Frame 1(반동)에서는 중심 잔광만 남기고 연기·탄피로 전환
        if (f === 0 || (x + y) % 2 === 0) {
          c.fxBegin();
          c.px(x, y + yOffset, lut[palIdx]);
          c.fxEnd();
        }
        continue;
      }
      c.px(x, y + yOffset, lut[palIdx]);
    }
  }

  if (useAtk) {
    const { dx, dy } = dir8Vector(dir);
    const [mx, my] = RIFLE_MUZZLE_TIP[dir];
    const evolved = isEvolvedPalette(palette);
    if (dir === 'NW' || evolved) {
      // 누락되어 있던 NW 방향 총구 섬광 보완 & 개틀링 진화 시 황금 회전 총구 섬광 추가
      c.stampMuzzleBlast(mx, my + yOffset, dx, dy, f, evolved ? 'GOLD' : 'FIRE');
    } else {
      // 48x48 여백으로 뻗는 전방 가우스 예광선(f=0) & 반동 연기·약실 탄피 배출(f=1)
      c.fxBegin();
      const perpX = -dy;
      const perpY = dx;
      if (f === 0) {
        for (let s = 2; s <= 6; s += 1) {
          c.px(mx + dx * s, my + yOffset + dy * s, s <= 4 ? [255, 255, 255] : [252, 232, 86]);
        }
      } else {
        c.px(mx + dx * 4, my + yOffset + dy * 4, [235, 119, 36]);
        c.px(mx + dx * 6, my + yOffset + dy * 6, [98, 95, 101]);
        const sx = mx - dx * 4 + perpX * 3;
        const sy = my + yOffset - dy * 4 + perpY * 3 - 2;
        c.px(sx, sy, [254, 215, 90]);
        c.px(sx - perpX, sy + 1, [192, 140, 69]);
      }
      c.fxEnd();
    }
  }
}

function detectCommanderFaction(palette: FactionPalette): 'IRONCLAD' | 'HIVE' | 'LUMEN' {
  const [r, g, b] = hexToRgb(palette.primary);
  if (r > 180 && g > 150 && b < 130) {
    return 'LUMEN';
  }
  if (r > g + 20 && b > g + 20) {
    return 'HIVE';
  }
  return 'IRONCLAD';
}

// ─────────────────────────── 1. 노바 기동군 (NOVA TASKFORCE) ───────────────────────────

function drawSoldier32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  // IMG_2485.png (8방향 IDLE) & IMG_2486.png (8방향 ATTACK) 원본 100% 직결!
  stamp8DirSheet(c, palette, frame, dir, anim, 0, undefined, true);
}

function drawIroncladCommander32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const isBack = dir === 'N' || dir === 'NE' || dir === 'NW';
  const capeShift =
    dir === 'E' ? -3 : dir === 'W' ? 3 : dir === 'SE' || dir === 'NE' ? -2 : dir === 'SW' || dir === 'NW' ? 2 : 0;

  const paintCape = (): void => {
    const minX = dir === 'E' ? 4 : 4;
    const maxX = dir === 'W' ? 27 : 27;
    for (let y = 12; y <= 28; y += 1) {
      const halfW = Math.min(11, 5 + Math.floor((y - 11) * 0.4));
      for (let x = 16 - halfW; x <= 15 + halfW; x += 1) {
        const cx = x + capeShift;
        if (cx < minX || cx > maxX) continue;
        if (x === 16 - halfW || x === 15 + halfW || y === 28) {
          c.px(cx, y, OUTLINE_RGB);
        } else if (y === 27) {
          c.px(cx, y, sp.trim.t4);
        } else {
          const edgeDist = Math.min(x - (16 - halfW), 15 + halfW - x);
          c.px(cx, y, edgeDist <= 2 ? sp.crimson.t3 : sp.crimson.t1);
        }
      }
    }
  };

  if (!isBack) paintCape();
  stamp8DirSheet(c, palette, frame, dir, anim, 0, undefined, true);
  if (isBack) paintCape();

  // 지휘 비콘 안테나 & 투구 금장 크레스트
  const antX = dir === 'W' || dir === 'SW' || dir === 'NW' ? 21 : 10;
  c.vLine(antX, 0, 4, OUTLINE_RGB);
  c.vLine(antX, 1, 4, sp.metal.t3);
  c.px(antX, 0, f === 0 ? sp.eyeGlow : sp.crimson.t3);
}

function drawFlamer32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const tankRamp = makeRamp8(sp.crimson.t3, sp.crimson.t0, sp.trim.t4);

  stamp8DirSheet(c, palette, frame, dir, anim, 0, sp.trim.t4, false);

  // 등면 대형 쌍열 프로메튬 연료 실린더 (8방향 위치 자동 대응)
  if (dir === 'E') {
    c.partDome(8, 7, 3.6, 4.5, tankRamp, { trim: sp.trim, trimBottom: true });
  } else if (dir === 'W') {
    c.partDome(23, 7, 3.6, 4.5, tankRamp, { trim: sp.trim, trimBottom: true });
  } else if (dir === 'N' || dir === 'NE' || dir === 'NW') {
    c.symPartDome(11, 10, 3.6, 5.2, tankRamp, { trim: sp.trim, trimBottom: true });
  } else {
    c.symPartDome(9, 4, 3.0, 3.2, tankRamp, { trim: sp.trim, trimBottom: true });
  }

  // 공격 시 조준 방향으로 대형 화염 방사 (진화 소각 분대: 청백 플라즈마 고열 화염)!
  if (anim === 'ATTACK') {
    const { dx, dy } = dir8Vector(dir);
    c.stampMuzzleBlast(16 + dx * 10, 18 + dy * 9, dx, dy, f, isEvolvedPalette(palette) ? 'PLASMA' : 'FIRE');
  }
}

function drawWalker32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const metalRamp = makeRamp8(sp.metal.t3, sp.metal.t0, sp.white);
  const recoil = anim === 'ATTACK' ? 1 : 0;

  if (dir === 'E') {
    c.partCapsule(9, 8 + recoil, 6, 1 + recoil, 2.5, metalRamp);
  } else if (dir === 'W') {
    c.partCapsule(22, 8 + recoil, 25, 1 + recoil, 2.5, metalRamp);
  } else {
    c.symPartCapsule(9, 7 + recoil, 7, 1 + recoil, 2.5, metalRamp);
    c.symPx(7, 1 + recoil, sp.crimson.t3);
    c.symPx(8, 3 + recoil, sp.trim.t4);
  }

  stamp8DirSheet(c, palette, frame, dir, anim, 1, undefined, false);

  if (anim === 'ATTACK') {
    const theme = isEvolvedPalette(palette) ? 'GOLD' : 'FIRE';
    if (dir === 'E' || dir === 'W') {
      const bx = dir === 'E' ? 6 : 25;
      c.stampMuzzleBlast(bx, 3, 0, -1, f, theme);
    } else {
      c.stampMuzzleBlast(7, 3, -0.3, -1, f, theme);
      c.stampMuzzleBlast(24, 3, 0.3, -1, f, theme);
    }
  }
}

function drawDrone32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const metalRamp = makeRamp8(sp.metal.t3, sp.metal.t0, sp.white);
  const yOff = f === 0 ? 0 : -1;
  const { dx, dy } = dir8Vector(dir);
  const hx = Math.round(dx * 2);

  c.symVLine(11, 2 + yOff, 6 + yOff, OUTLINE_RGB);
  c.symVLine(10, 3 + yOff, 6 + yOff, sp.metal.t3);
  c.symPx(10, 2 + yOff, sp.eyeGlow);

  c.symPartCapsule(10, 19 + yOff, 7, 25 + yOff, 2.0, metalRamp);
  c.symPartCapsule(7, 25 + yOff, 12, 28 + yOff, 1.8, sp.body);
  c.partDome(15.5 + hx, 28 + yOff, 3.0, 2.0, makeRamp8(sp.eyeGlow, sp.eyeSocket, sp.white));

  c.symPartDome(4.5, 13 + yOff, 3.8, 5.2, sp.body, {
    trim: sp.trim,
    trimBottom: true,
    trimInner: true,
  });
  c.symRect(3, 12 + yOff, 3, 3, OUTLINE_RGB);
  c.symPx(4, 13 + yOff, sp.eyeGlow);
  c.symPx(4, 19 + yOff, sp.eyeGlow);
  c.symPx(5, 19 + yOff, sp.white);

  c.partDome(15.5 + hx, 13 + yOff, 7.2, 6.8, sp.body, { trim: sp.trim, trimBottom: true });
  if (dir !== 'N' && dir !== 'NE' && dir !== 'NW') {
    c.sculptVisorFace(15 + yOff, sp.body, sp.trim, sp.eyeGlow, 'RESPIRATOR', hx);
  }

  c.rect(13 + hx, 6 + yOff, 6, 6, OUTLINE_RGB);
  c.rect(14 + hx, 7 + yOff, 4, 4, sp.trim.t3);
  c.vLine(15 + hx, 7 + yOff, 10 + yOff, sp.white);
  c.vLine(16 + hx, 7 + yOff, 10 + yOff, sp.white);
  c.hLine(14 + hx, 17 + hx, 8 + yOff, sp.white);
  c.hLine(14 + hx, 17 + hx, 9 + yOff, sp.eyeGlow);

  if (anim === 'ATTACK') {
    c.stampNanoHeal(16 + dx * 6, 26 + dy * 3, dx, dy, f, isEvolvedPalette(palette));
  }
}

