// ─────────────────────────── 5. 신규 12종 32x32 전용 드로잉 (M5.1 노바 기동군 분대 4 + M6 블라이트 8) ───────────────────────────

function isBackDir(dir: SpriteDir8): boolean {
  return dir === 'N' || dir === 'NE' || dir === 'NW';
}

/** 좌(-1) / 정면·후면(0) / 우(+1) 시점 부호 */
function sideSign(dir: SpriteDir8): number {
  if (dir === 'E' || dir === 'NE' || dir === 'SE') return 1;
  if (dir === 'W' || dir === 'NW' || dir === 'SW') return -1;
  return 0;
}

function drawLine(c: SculptCanvas32, x0: number, y0: number, x1: number, y1: number, col: Rgb): void {
  let x = Math.round(x0);
  let y = Math.round(y0);
  const xe = Math.round(x1);
  const ye = Math.round(y1);
  const ddx = Math.abs(xe - x);
  const ddy = -Math.abs(ye - y);
  const sx = x < xe ? 1 : -1;
  const sy = y < ye ? 1 : -1;
  let err = ddx + ddy;
  for (let guard = 0; guard < 96; guard += 1) {
    c.px(x, y, col);
    if (x === xe && y === ye) break;
    const e2 = 2 * err;
    if (e2 >= ddy) {
      err += ddy;
      x += sx;
    }
    if (e2 <= ddx) {
      err += ddx;
      y += sy;
    }
  }
}

/** 결정론적 지그재그 번개: 바깥 1px 글로우 + 흰 코어 */
function drawBolt(
  c: SculptCanvas32,
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  seed: number,
  glow: Rgb,
  core: Rgb
): void {
  const segs = 5;
  const len = Math.hypot(x1 - x0, y1 - y0) || 1;
  const nx = -(y1 - y0) / len;
  const ny = (x1 - x0) / len;
  const pts: Array<[number, number]> = [[x0, y0]];
  for (let i = 1; i < segs; i += 1) {
    const t = i / segs;
    const j = (((seed * 7 + i * 13) % 5) - 2) * 0.9;
    pts.push([x0 + (x1 - x0) * t + nx * j, y0 + (y1 - y0) * t + ny * j]);
  }
  pts.push([x1, y1]);
  for (let i = 0; i < pts.length - 1; i += 1) {
    const [ax, ay] = pts[i];
    const [bx, by] = pts[i + 1];
    drawLine(c, ax + 1, ay, bx + 1, by, glow);
    drawLine(c, ax, ay + 1, bx, by + 1, glow);
  }
  for (let i = 0; i < pts.length - 1; i += 1) {
    drawLine(c, pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], core);
  }
}

/** 모서리를 깎은 판금 타워 실드 (좌상단 광원, 금장 테두리, 관측 슬릿) */
function drawTowerShield(
  c: SculptCanvas32,
  x0: number,
  y0: number,
  w: number,
  h: number,
  plate: ClusterRamp8,
  trim: TrimRamp5,
  slit: Rgb,
  emblem: Rgb
): void {
  const x1 = x0 + w - 1;
  const y1 = y0 + h - 1;
  const inside = (x: number, y: number): boolean => {
    if (x < x0 || x > x1 || y < y0 || y > y1) return false;
    const cornerTop = (x === x0 || x === x1) && y === y0;
    const cornerBot = (x - x0 < 2 || x1 - x < 2) && y1 - y < 2 && !(x - x0 >= 1 && x1 - x >= 1 && y === y1 - 1);
    return !cornerTop && !cornerBot;
  };
  for (let y = y0 - 1; y <= y1 + 1; y += 1) {
    for (let x = x0 - 1; x <= x1 + 1; x += 1) {
      if (!inside(x, y)) {
        if (inside(x - 1, y) || inside(x + 1, y) || inside(x, y - 1) || inside(x, y + 1)) {
          c.px(x, y, OUTLINE_RGB);
        }
        continue;
      }
      const edgeL = !inside(x - 1, y);
      const edgeR = !inside(x + 1, y);
      const edgeT = !inside(x, y - 1);
      const edgeB = !inside(x, y + 1);
      let col: Rgb;
      if (edgeT) col = trim.t4;
      else if (edgeB) col = trim.t0;
      else if (edgeL) col = trim.t3;
      else if (edgeR) col = trim.t1;
      else {
        const u = (x - x0) / Math.max(1, w - 1);
        const v = (y - y0) / Math.max(1, h - 1);
        const k = u * 0.55 + v * 0.75;
        col = k < 0.25 ? plate.c7 : k < 0.45 ? plate.c6 : k < 0.7 ? plate.c5 : k < 0.95 ? plate.c4 : k < 1.15 ? plate.c3 : plate.c2;
      }
      c.px(x, y, col);
    }
  }
  // 관측 슬릿 + 중앙 쉐브론 문장
  const sy = y0 + 3;
  c.hLine(x0 + 2, x1 - 2, sy, OUTLINE_RGB);
  c.hLine(x0 + 3, x1 - 3, sy, slit);
  c.px(x0 + 3, sy, lighten(slit, 0.6));
  const mx = Math.floor((x0 + x1) / 2);
  const my = y0 + Math.floor(h * 0.58);
  for (let i = 0; i < Math.min(3, Math.floor(w / 3)); i += 1) {
    c.px(mx - i, my - 1 + i, emblem);
    c.px(mx + i + ((w + 1) % 2 === 0 ? 0 : 0), my - 1 + i, darken(emblem, 0.25));
  }
  // 리벳
  c.px(x0 + 1, y1 - 3, trim.t2);
  c.px(x1 - 1, y1 - 3, trim.t1);
}

function bugLegPairs(
  c: SculptCanvas32,
  cx: number,
  cy: number,
  pairs: number,
  gap: number,
  inner: number,
  reach: number,
  frame: number,
  anim: SpriteAnim,
  ramp: ClusterRamp8,
  tip: Rgb,
  r: number = 1.4
): void {
  for (let i = 0; i < pairs; i += 1) {
    const ly = cy + (i - (pairs - 1) / 2) * gap;
    const phase = anim === 'WALK' ? ((i + frame) % 2 === 0 ? -1 : 1) : (i + frame) % 2 === 0 ? 0 : 1;
    const footY = ly + 3 + phase + (i - (pairs - 1) / 2) * 1.2;
    const kneeLX = cx - inner - reach * 0.6;
    const footLX = cx - inner - reach;
    c.partCapsule(cx - inner, ly, kneeLX, ly - 1.5, r, ramp);
    c.partCapsule(kneeLX, ly - 1.5, footLX, footY, r * 0.85, ramp);
    c.partCapsule(31 - (cx - inner), ly, 31 - kneeLX, ly - 1.5, r, ramp);
    c.partCapsule(31 - kneeLX, ly - 1.5, 31 - footLX, footY - phase * 2, r * 0.85, ramp);
    c.px(footLX, footY + 1, tip);
    c.px(31 - footLX, footY + 1 - phase * 2, tip);
  }
}

function glowEyes(c: SculptCanvas32, x: number, y: number, spread: number, col: Rgb, f: number): void {
  for (const sx of [-1, 1]) {
    const ex = Math.round(x + sx * spread);
    c.px(ex, y, f === 1 ? lighten(col, 0.5) : col);
    c.px(ex, y - 1, OUTLINE_RGB);
    c.px(ex + (sx < 0 ? -1 : 1), y, OUTLINE_RGB);
    c.px(ex - (sx < 0 ? -1 : 1), y, darken(col, 0.35));
  }
}

// ── 노바 기동군 신규 분대 4종 ──

function drawSniper32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const gunRamp = makeRamp8(sp.metal.t2, sp.metal.t0, sp.white);
  const cloakRamp = makeRamp8(mixRgb(sp.body.c3, [92, 104, 72], 0.55), mixRgb(sp.body.c1, [36, 42, 30], 0.6), sp.trim.t4);
  const lens: Rgb = [255, 92, 72];

  // 위장 망토 (등 뒤로 떨어지는 짧은 케이프)
  const paintCloak = (): void => {
    const shift = -sideSign(dir) * 2;
    for (let y = 12; y <= 25; y += 1) {
      const half = Math.min(9, 5 + Math.floor((y - 12) * 0.45));
      for (let x = 16 - half; x <= 15 + half; x += 1) {
        const jag = y === 25 && (x + f) % 3 === 0;
        if (jag) continue;
        const edge = x === 16 - half || x === 15 + half || y === 25 || (y === 24 && (x + f) % 3 === 0);
        const u = (x - (16 - half)) / (2 * half);
        c.px(x + shift, y, edge ? OUTLINE_RGB : u < 0.3 ? cloakRamp.c5 : u < 0.7 ? cloakRamp.c4 : cloakRamp.c2);
      }
    }
  };
  if (!back) paintCloak();

  stamp8DirSheet(c, palette, frame, dir, anim, 0, lens, false);

  if (back) paintCloak();

  // 위장 후드 + 붉은 단안 조준경
  c.partDome(15.5, 4, 6.2, 2.6, cloakRamp);
  if (!back) {
    const lx = 15 + Math.round(dx * 3) + (sideSign(dir) === 0 ? 3 : 0);
    c.rect(lx - 1, 7, 3, 3, OUTLINE_RGB);
    c.px(lx, 8, lens);
    c.px(lx - 1, 7, sp.metal.t3);
    c.px(lx + 1, 8, lighten(lens, 0.5));
  }

  if (anim === 'ATTACK') {
    // 조준 사격: 장포신이 조준 방향으로 길게 뻗는다
    const recoil = f === 1 ? 1 : 0;
    const bx = 16 - dx * recoil;
    const by = 18 - dy * recoil;
    const tx = bx + dx * 15;
    const ty = by + dy * 13;
    const evolved = isEvolvedPalette(palette);
    c.partCapsule(bx - dx * 4, by - dy * 3, bx + dx * 6, by + dy * 5, 1.8, gunRamp);
    c.partCapsule(bx + dx * 6, by + dy * 5, tx, ty, 0.9, gunRamp);
    c.partDome(bx + dx * 2, by + dy * 2 - 2, 2.2, 1.2, gunRamp);
    c.px(bx + dx * 2 - 1, by + dy * 2 - 2, lens);
    c.stampMuzzleBlast(tx + dx * 2, ty + dy * 2, dx, dy, f, evolved ? 'CRIMSON' : 'FIRE');
    c.fxBegin();
    if (f === 0) {
      drawLine(c, tx + dx * 4, ty + dy * 4, tx + dx * 12, ty + dy * 12, evolved ? [255, 96, 82] : [255, 244, 200]);
      drawLine(c, tx + dx * 3, ty + dy * 3, tx + dx * 9, ty + dy * 9, [255, 255, 255]);
    } else if (evolved) {
      // 처형자 진화 반동: 진홍·황금 공기 파열 링
      const perpX = -dy;
      const perpY = dx;
      for (const side of [-2, -1, 1, 2]) {
        c.px(tx + dx * 4 + perpX * side, ty + dy * 4 + perpY * side, Math.abs(side) === 1 ? [255, 207, 74] : [255, 56, 88]);
      }
    }
    c.fxEnd();
  } else {
    // 대기/이동: 대물 저격총을 사선으로 거치 (총구가 어깨 위로 솟음)
    const s = sideSign(dir) < 0 ? -1 : 1;
    const ax = 15.5 - s * 7;
    const bx = 15.5 + s * 9;
    const lift = f;
    c.partCapsule(ax, 25, 15.5 + s * 3, 15 - lift, 1.7, gunRamp);
    c.partCapsule(15.5 + s * 3, 15 - lift, bx, 1 - lift, 0.9, gunRamp);
    c.partDome(15.5 + s * 1, 17 - lift, 2.4, 1.3, gunRamp);
    c.px(15.5 + s * 1 - s * 2, 17 - lift, lens);
    c.px(bx, 1 - lift, sp.trim.t4);
    c.px(bx - s, 2 - lift, sp.trim.t3);
  }
}

function drawShielder32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const plate = makeRamp8(mixRgb(sp.metal.t3, sp.body.c5, 0.35), sp.metal.t0, sp.white);
  const bash = anim === 'ATTACK' ? (f === 0 ? 3 : 1) : 0;
  const bob = anim === 'WALK' ? frame % 2 : 0;
  const ox = Math.round(dx * bash);
  const oy = Math.round(dy * bash * 0.6);

  const paintShield = (): void => {
    if (dir === 'E' || dir === 'W') {
      // 측면: 두께 있는 판이 정면을 가린다
      const x = dir === 'E' ? 21 : 6;
      drawTowerShield(c, x + ox, 9 + bob, 5, 20, plate, sp.trim, sp.eyeGlow, sp.trim.t4);
    } else if (back) {
      // 후면: 등에 멘 방패 뒷면 (보강 프레임)
      const s = sideSign(dir);
      drawTowerShield(c, 9 + s * 3, 10 + bob, 14, 17, makeRamp8(sp.metal.t2, sp.metal.t0, sp.metal.t4), sp.trim, sp.metal.t1, sp.metal.t2);
      c.vLine(15 + s * 3, 12 + bob, 25 + bob, sp.metal.t1);
      c.vLine(16 + s * 3, 12 + bob, 25 + bob, sp.metal.t0);
      c.hLine(11 + s * 3, 20 + s * 3, 18 + bob, sp.metal.t1);
    } else {
      const s = sideSign(dir);
      drawTowerShield(c, 4 + s * 7 + ox, 12 + bob + oy, 13, 17, plate, sp.trim, sp.eyeGlow, sp.trim.t4);
    }
  };

  stamp8DirSheet(c, palette, frame, dir, anim, 0, sp.eyeGlow, false);
  // 견갑 위 상단 증가 장갑
  c.symPartDome(7.5, 12, 3.4, 2.2, plate, { trim: sp.trim, trimBottom: true });
  paintShield();

  if (anim === 'ATTACK') {
    // 방패 강타 전용 이중 충격파 판 (성벽 분대 진화 시 황금 충격파)
    const hx = 16 + dx * 13;
    const hy = 19 + dy * 10;
    c.stampShieldBash(hx, hy, dx, dy, f, isEvolvedPalette(palette));
  }
}

function drawSapper32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const s = sideSign(dir);
  const evolved = isEvolvedPalette(palette);
  // 포탑 공병: 접이식 포탑 포드 (금속 몸체 + 시안 센서)
  const mineRamp = makeRamp8(sp.metal.t3, sp.metal.t0, sp.white);
  const led: Rgb = f === 0 ? (evolved ? [255, 215, 74] : [95, 224, 255]) : [32, 96, 140];
  const hazard = sp.trim.t3;

  const mine = (x: number, y: number, rx: number): void => {
    c.partDome(x, y, rx, rx * 0.55, mineRamp, { trim: sp.trim, trimBottom: true });
    c.px(x, y - 1, led);
    c.px(x - 1, y - 1, OUTLINE_RGB);
    c.px(x + 1, y - 1, OUTLINE_RGB);
  };

  // 등짐: 접이식 포탑 포드 랙
  const paintPack = (): void => {
    const px = 15.5 - s * 3;
    c.partDome(px, 13, 6.2, 5.6, makeRamp8(sp.metal.t2, sp.metal.t0, sp.metal.t4), { trim: sp.trim, trimBottom: true });
    mine(px - 2.5, 9, 3.2);
    mine(px + 2.5, 10, 3.2);
    mine(px, 14, 3.4);
    // 경고 줄무늬
    for (let k = 0; k < 4; k += 1) c.px(px - 4 + k * 2, 18, k % 2 === 0 ? hazard : OUTLINE_RGB);
  };

  if (back) {
    stamp8DirSheet(c, palette, frame, dir, anim, 0, sp.trim.t4, false);
    paintPack();
  } else {
    stamp8DirSheet(c, palette, frame, dir, anim, 0, sp.trim.t4, false);
    // 정면: 견갑 위에 고정한 포탑 포드 랙
    if (s >= 0) mine(6, 9, 3.4);
    if (s <= 0) mine(25, 9, 3.4);
    // 허리 탄띠: 경고 줄무늬
    for (let x = 10; x <= 21; x += 1) {
      if (c.isOpaque(x, 21)) c.px(x, 21, (x >> 1) % 2 === 0 ? hazard : OUTLINE_RGB);
    }
  }

  // 탐지 안테나
  const ax = s < 0 ? 22 : 9;
  c.vLine(ax, 1, 6, OUTLINE_RGB);
  c.vLine(ax + (s < 0 ? -1 : 1), 2, 6, sp.metal.t3);
  c.px(ax + (s < 0 ? -1 : 1), 1, led);

  if (anim === 'ATTACK') {
    // 설치: 발치 앞에 포탑 포드를 내려놓고 흙먼지와 스파크가 튄다 (이펙트 레이어)
    c.fxBegin();
    const mx = 16 + dx * 9;
    const my = 27 + dy * 2;
    mine(mx, my, 4.2);
    c.px(mx, my - 1, f === 0 ? [255, 240, 200] : led);
    const dust: Rgb = [150, 128, 98];
    c.px(mx - 5, my - 2 - f, dust);
    c.px(mx + 5, my - 2 - f, dust);
    c.px(mx - 4, my - 4 - f, lighten(dust, 0.3));
    c.px(mx + 4, my - 4 - f, lighten(dust, 0.3));
    c.stampMuzzleBlast(16 + dx * 6, 22 + dy * 4, dx * 0.6, 1, f, evolved ? 'PLASMA' : 'FIRE');
    c.fxEnd();
  } else if (!back) {
    // 손에 든 포탑 포드
    const hx = s < 0 ? 5 : 26;
    mine(hx, 22 + f, 3.8);
    c.px(hx - 2, 23 + f, hazard);
    c.px(hx + 2, 23 + f, hazard);
  }
}

function drawTesla32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const s = sideSign(dir);
  const evolved = isEvolvedPalette(palette);
  const coilRamp = makeRamp8([196, 120, 64], [82, 40, 18], [255, 230, 190]);
  const orbRamp = evolved
    ? makeRamp8([208, 136, 255], [72, 28, 148], sp.white)
    : makeRamp8([120, 236, 255], [20, 90, 160], sp.white);
  const glow: Rgb = evolved ? [196, 120, 255] : [95, 224, 255];
  const charge = anim === 'ATTACK' ? 1 : f;

  // 등에 멘 코일 탑: 구리 코일 + 금장 절연 링 + 축전 구체
  const cx = back ? 15.5 : s > 0 ? 8 : s < 0 ? 23 : 7;
  const paintCoil = (): void => {
    c.partCapsule(cx, 17, cx, 6, 2.6, coilRamp);
    for (let y = 8; y <= 16; y += 3) {
      c.hLine(Math.round(cx - 2), Math.round(cx + 2), y, sp.trim.t3);
      c.px(cx - 2, y, sp.trim.t4);
      c.hLine(Math.round(cx - 3), Math.round(cx + 3), y + 1, OUTLINE_RGB);
    }
    c.partDome(cx, 4, 3.4 + charge * 0.4, 3.0 + charge * 0.4, orbRamp);
    c.px(cx - 1, 3, sp.white);
  };

  stamp8DirSheet(c, palette, frame, dir, anim, 0, glow, false);
  paintCoil();

  // 반대편 손목 방전 단자
  const wx = cx < 16 ? 26 : 5;
  c.partDome(wx, 20, 2.0, 2.0, coilRamp);
  c.px(wx, 19, f === 0 ? glow : sp.white);

  if (anim === 'ATTACK') {
    // 구체에서 조준 방향으로 연쇄 번개 (폭풍 포대 진화 시 청백·자주 과충전 3중 번개)
    const tx = 16 + dx * 17;
    const ty = 16 + dy * 15;
    c.fxBegin();
    drawBolt(c, cx, 4, tx, ty, frame + 1, glow, sp.white);
    drawBolt(c, wx, 20, tx, ty, frame + 4, evolved ? [95, 224, 255] : glow, sp.white);
    if (evolved) {
      drawBolt(c, cx, 4, tx - dy * 4, ty + dx * 4, frame + 2, [95, 224, 255], [240, 210, 255]);
    }
    c.partDome(tx, ty, evolved ? 2.6 : 2.2, evolved ? 2.6 : 2.2, orbRamp);
    c.px(tx, ty, sp.white);
    c.fxEnd();
  } else if (f === 1) {
    // 대기 방전 스파크
    c.fxBegin();
    c.px(cx - 4, 2, glow);
    c.px(cx + 4, 5, glow);
    c.px(cx + 3, 1, sp.white);
    c.fxEnd();
  }
}

// ── 블라이트 M6 적 8종 ──

function drawCharger32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const hornRamp = anim === 'ATTACK' ? makeRamp8(sp.trim.t4, sp.trim.t1, sp.white) : makeRamp8(sp.bone.t3, sp.bone.t0, sp.white);
  const legRamp = makeRamp8(sp.body.c3, sp.body.c0, sp.body.c6);
  const crouch = anim === 'ATTACK' ? 1 : 0;
  const cy = 17 + crouch;
  const hx = 15.5 + dx * 7;
  const hy = cy + 2 + dy * 5;

  // 돌진 예고: 뒤편 흙먼지
  if (anim === 'ATTACK') {
    c.fxBegin();
    const dust: Rgb = [176, 150, 116];
    const bx = 15.5 - dx * 11;
    const by = 25 - dy * 4;
    c.partDome(bx, by, 2.6 + f, 1.8 + f * 0.5, makeRamp8(dust, darken(dust, 0.4), [240, 226, 200]));
    c.partDome(bx - dy * 4 - dx * 2, by + dx * 2, 1.6, 1.2, makeRamp8(dust, darken(dust, 0.4), [240, 226, 200]));
    c.fxEnd();
  }

  bugLegPairs(c, 15.5, cy + 2, 3, 3.6, 5, 6, frame, anim, legRamp, sp.bone.t3, 1.5);

  const head = (): void => {
    c.partDome(hx, hy, 5.2, 4.0, sp.body, { trim: sp.trim, trimBottom: true });
    // 좌우 엄니
    const px = -dy;
    const py = dx;
    for (const k of [-1, 1]) {
      const bx = hx + px * k * 3;
      const by = hy + py * k * 2 + 1;
      c.partCapsule(bx, by, bx + dx * 4 + px * k, by + dy * 3 + 2, 1.1, hornRamp);
    }
    // 중앙 대형 뿔: 앞으로 솟아 위로 휜다
    c.partCapsule(hx, hy - 1, hx + dx * 4, hy - 6 + dy * 2, 1.9, hornRamp);
    c.partCapsule(hx + dx * 4, hy - 6 + dy * 2, hx + dx * 6, hy - 10 + dy * 2, 1.0, hornRamp);
    if (!back) glowEyes(c, hx, hy + 1, 2.5, anim === 'ATTACK' ? sp.white : sp.trim.t4, f);
  };

  if (back) head();
  // 등딱지: 2단 판갑 + 척추 돌기
  c.partDome(15.5 - dx * 2, cy - 1 - dy, 9.2, 6.6, sp.body, { trim: sp.trim, trimBottom: true });
  c.partDome(15.5 - dx * 3, cy - 3 - dy, 6.0, 3.6, makeRamp8(sp.body.c6, sp.body.c2, sp.white));
  for (let k = -1; k <= 1; k += 1) {
    const sx = 15.5 - dx * 2 - dx * k * 3 + (dx === 0 ? 0 : 0);
    const sy = cy - 6 - dy * k * 2 + Math.abs(k);
    c.px(sx, sy, sp.trim.t4);
    c.px(sx, sy + 1, sp.trim.t2);
  }
  if (!back) head();
}

function drawSporer32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const sacRamp = makeRamp8(sp.trim.t3, sp.body.c2, [250, 255, 214]);
  const legRamp = makeRamp8(sp.body.c3, sp.body.c0, sp.body.c6);
  const squeeze = anim === 'ATTACK' ? (f === 0 ? -1.2 : -0.4) : f * 0.5;

  bugLegPairs(c, 15.5, 23, 2, 4, 4, 5, frame, anim, legRamp, sp.bone.t3, 1.3);

  const tube = (): void => {
    const bx = 15.5 + dx * 4;
    const by = 22 + dy * 2;
    const tx = 15.5 + dx * 10;
    const ty = 22 + dy * 6;
    c.partCapsule(bx, by, tx, ty, 2.0, sp.body);
    c.partDome(tx, ty, 2.2, 2.0, makeRamp8(sp.trim.t2, sp.trim.t0, sp.trim.t4));
    c.px(tx, ty, OUTLINE_RGB);
    c.px(tx + 1, ty, darken(sp.trim.t1, 0.4));
  };

  if (back) tube();
  c.partDome(15.5, 21, 7.4, 5.0, sp.body, { trim: sp.trim, trimBottom: true });
  // 포자낭: 반투명하게 부푼 주머니 + 어두운 포자 구멍
  const sx = 15.5 - dx * 2;
  const sy = 12 - dy;
  c.partDome(sx, sy, 7.6 + squeeze, 7.0 + squeeze, sacRamp, { trim: sp.trim, trimBottom: true });
  const pores: Array<[number, number]> = [[-3, 1], [2, -2], [3, 3], [-1, 4]];
  for (const [px, py] of pores) {
    c.px(sx + px, sy + py, sp.body.c2);
    c.px(sx + px + 1, sy + py, sp.body.c3);
    c.px(sx + px, sy + py - 1, lighten(sp.trim.t3, 0.35));
  }
  // 낭 표면 핏줄
  drawLine(c, sx - 5, sy + 2, sx - 2, sy - 3, sp.trim.t1);
  if (!back) {
    tube();
    glowEyes(c, 15.5 + dx * 3, 19 + dy, 2.5, sp.trim.t4, f);
  }

  if (anim === 'ATTACK') {
    c.stampMuzzleBlast(15.5 + dx * 13, 22 + dy * 9, dx, dy, f, 'ACID');
  } else if (f === 1) {
    c.fxBegin();
    c.px(sx + 2, sy - 8, sp.trim.t4);
    c.px(sx - 4, sy - 7, sp.trim.t3);
    c.fxEnd();
  }
}

function drawSplitter32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const legRamp = makeRamp8(sp.body.c3, sp.body.c0, sp.body.c6);
  const apart = anim === 'ATTACK' ? (f === 0 ? 2 : 1) : 0;
  const hx = Math.round(dx * 2);
  const seamHot: Rgb = anim === 'ATTACK' ? sp.white : f === 1 ? lighten(sp.trim.t3, 0.4) : sp.trim.t3;

  bugLegPairs(c, 15.5, 21, 3, 3.2, 6, 5, frame, anim, legRamp, sp.bone.t3, 1.3);

  // 쌍둥이 엽(lobe): 서로 떨어지려는 두 몸통
  c.partDome(10.5 - apart, 15, 6.4, 7.6, sp.body, { trim: sp.trim, trimBottom: true, trimInnerSide: 'RIGHT' });
  c.partDome(20.5 + apart, 15, 6.4, 7.6, sp.body, { trim: sp.trim, trimBottom: true, trimInnerSide: 'LEFT', specOffsetX: 0.1 });

  // 갈라지는 발광 이음매 (지그재그)
  for (let y = 7; y <= 23; y += 1) {
    const zig = (y + (anim === 'ATTACK' ? 0 : f)) % 4 < 2 ? 0 : 1;
    const x = 15 + zig;
    c.px(x, y, seamHot);
    if (apart > 0) {
      for (let k = 1; k <= apart; k += 1) {
        c.px(x - k, y, k === apart ? sp.trim.t2 : sp.trim.t4);
        c.px(x + k, y, k === apart ? sp.trim.t2 : sp.trim.t4);
      }
    } else {
      c.px(x - 1, y, sp.trim.t1);
      c.px(x + 1, y, darken(sp.trim.t1, 0.3));
    }
  }

  if (!back) {
    // 엽마다 눈 3개 + 아래 공용 입
    for (const lx of [10.5 - apart + hx, 20.5 + apart + hx]) {
      c.px(lx - 2, 15, sp.trim.t4);
      c.px(lx + 1, 14, sp.trim.t4);
      c.px(lx, 17, sp.trim.t3);
      c.px(lx - 2, 16, darken(sp.trim.t3, 0.4));
      c.px(lx + 1, 15, darken(sp.trim.t3, 0.4));
    }
    c.hLine(12 + hx, 19 + hx, 21, OUTLINE_RGB);
    for (let k = 12; k <= 19; k += 2) c.px(k + hx, 20, sp.bone.t4);
  } else {
    // 후면: 엽 위 등 돌기
    c.px(10.5 - apart, 10, sp.trim.t4);
    c.px(20.5 + apart, 10, sp.trim.t4);
  }

  if (anim === 'ATTACK') {
    c.stampBiteSnap(16 + dx * 10, 18 + dy * 9, dx, dy, f, 'CRIMSON');
  }
}

function drawBomber32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx } = dir8Vector(dir);
  const back = isBackDir(dir);
  const hx = Math.round(dx * 2);
  const legRamp = makeRamp8(sp.body.c3, sp.body.c0, sp.body.c6);
  const arming = anim === 'ATTACK';
  const swell = arming ? 1.2 + f * 0.6 : f * 0.4;
  const vein: Rgb = arming ? (f === 0 ? sp.white : [255, 236, 140]) : f === 1 ? [255, 236, 160] : sp.trim.t4;
  const veinDim: Rgb = arming ? sp.trim.t4 : sp.trim.t0;

  bugLegPairs(c, 15.5, 25, 2, 3, 3, 5, frame, anim, legRamp, sp.bone.t3, 1.3);
  c.partDome(15.5 + hx, 24, 5.6, 3.6, sp.body, { trim: sp.trim, trimBottom: true });

  // 폭발성 주머니: 금이 간 표피 사이로 내부 불빛이 샌다
  const sacRamp = makeRamp8(mixRgb(sp.body.c5, sp.trim.t2, 0.35), sp.body.c1, sp.trim.t4);
  c.partDome(15.5, 14, 8.6 + swell, 8.2 + swell, sacRamp, { trim: sp.trim, trimBottom: true });
  const cracks: Array<[number, number, number, number]> = [
    [10, 12, 14, 15],
    [14, 15, 13, 19],
    [14, 15, 18, 13],
    [18, 13, 21, 15],
    [18, 13, 17, 9],
    [21, 15, 20, 19],
  ];
  for (const [x0, y0, x1, y1] of cracks) {
    drawLine(c, x0 + 1, y0 + 1, x1 + 1, y1 + 1, veinDim);
    drawLine(c, x0, y0, x1, y1, vein);
  }
  c.px(14, 15, sp.white);
  c.px(18, 13, arming || f === 1 ? sp.white : [255, 236, 160]);

  // 머리 위 도화선 줄기 + 점화 구슬
  c.partCapsule(16, 6 - swell, 18, 1, 1.0, sp.body);
  c.partDome(18.5, 1.5, 1.6, 1.4, makeRamp8(sp.trim.t3, sp.trim.t1, sp.white));
  c.px(18, 1, f === 0 || arming ? sp.white : sp.trim.t4);

  if (!back) {
    glowEyes(c, 15.5 + hx, 24, 2, sp.trim.t4, f);
  }

  if (arming) {
    // 자폭 예고 섬광 스파크
    c.fxBegin();
    const r = 11 + f;
    for (let k = 0; k < 8; k += 1) {
      const a = (k / 8) * Math.PI * 2 + f * 0.4;
      c.px(15.5 + Math.cos(a) * r, 14 + Math.sin(a) * r, k % 2 === 0 ? sp.white : sp.trim.t4);
    }
    c.fxEnd();
  }
}

function drawShell32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const legRamp = makeRamp8(sp.body.c3, sp.body.c0, sp.body.c6);
  const shellRamp = makeRamp8(sp.body.c6, sp.body.c1, sp.white);
  const ram = anim === 'ATTACK' ? (f === 0 ? 2 : 1) : 0;

  bugLegPairs(c, 15.5, 22, 3, 3, 7, 4, frame, anim, legRamp, sp.trim.t3, 1.6);

  // 3겹 분절 갑각 (뒤→앞)
  for (let i = 0; i < 3; i += 1) {
    const t = i - 1;
    c.partDome(15.5 - dx * t * 3.5, 16 - dy * t * 3 - (i === 1 ? 1 : 0), 10.2 - Math.abs(t) * 1.2, 6.2, i === 1 ? shellRamp : sp.body, {
      trim: sp.trim,
      trimBottom: true,
    });
  }
  // 갑각 이음 홈 + 돌기
  for (let k = -1; k <= 1; k += 1) {
    c.px(15.5 + k * 4, 11, sp.trim.t4);
    c.px(15.5 + k * 4, 12, sp.trim.t2);
  }

  // 정면 방호판: 정면 피해 감소를 보여주는 두꺼운 은빛 판
  if (!back) {
    const fx = 15.5 + dx * (9 + ram);
    const fy = 19 + dy * (6 + ram);
    const plate = makeRamp8(sp.trim.t3, sp.body.c1, sp.white);
    if (dir === 'E' || dir === 'W') {
      c.partDome(fx, fy - 2, 3.0, 7.0, plate, { trim: sp.trim, trimBottom: true });
    } else {
      c.partDome(fx, fy, 7.4, 3.8, plate, { trim: sp.trim, trimBottom: true });
      c.hLine(Math.round(fx - 4), Math.round(fx + 4), Math.round(fy + 1), OUTLINE_RGB);
    }
    glowEyes(c, fx, Math.round(fy + (dir === 'E' || dir === 'W' ? 2 : 2)), dir === 'E' || dir === 'W' ? 0.6 : 2.5, [255, 120, 80], f);
  }

  if (anim === 'ATTACK') {
    c.stampBiteSnap(16 + dx * 12, 19 + dy * 10, dx, dy, f, 'CRIMSON');
  }
}

function drawNest32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  _dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const hatch = anim === 'ATTACK';
  const eggRamp = makeRamp8(sp.trim.t3, sp.body.c2, [255, 236, 236]);
  const fleshRamp = makeRamp8(sp.body.c6, sp.body.c1, sp.trim.t4);

  // 땅을 움켜쥔 촉수 뿌리
  const roots: Array<[number, number, number, number]> = [
    [6, 25, 1, 29],
    [10, 27, 6, 31],
    [21, 27, 25, 31],
    [25, 25, 30, 29],
  ];
  for (const [x0, y0, x1, y1] of roots) {
    c.partCapsule(x0, y0, x1 + (f === 1 ? 0 : 0), y1, 1.6, sp.body);
  }

  // 둥지 본체: 층층이 쌓인 점액 둔덕
  c.partDome(15.5, 22, 13.0, 7.6, sp.body, { trim: sp.trim, trimBottom: true });
  c.partDome(15.5, 16, 10.0, 7.0, fleshRamp);
  c.partDome(15.5, 11, 6.8, 5.0, sp.body);

  // 알 주머니 4개 (박동)
  const eggs: Array<[number, number, number]> = [
    [7, 19, 2.8],
    [24, 19, 2.8],
    [10, 12, 2.3],
    [21, 12, 2.3],
  ];
  eggs.forEach(([ex, ey, r], i) => {
    const pulse = (i + frame) % 2 === 0 ? 0.3 : 0;
    c.partDome(ex, ey, r + pulse, r * 1.1 + pulse, eggRamp, { trim: sp.trim, trimBottom: true });
    c.px(ex, ey, (i + frame) % 2 === 0 ? sp.trim.t4 : sp.trim.t2);
  });

  // 중앙 산란구: 여닫히는 구멍과 내부 빛
  const open = hatch ? 3.2 + f * 0.6 : 2.0 + f * 0.4;
  c.partDome(15.5, 18, open + 1.6, open, makeRamp8([28, 6, 12], [8, 2, 4], sp.trim.t3));
  c.px(15, 18, hatch ? sp.white : sp.trim.t3);
  c.px(16, 18, hatch ? sp.trim.t4 : sp.trim.t2);
  for (let k = -2; k <= 2; k += 2) c.px(15.5 + k, 18 - open, sp.bone.t4);

  // 꼭대기 촉수 돌기
  c.partCapsule(15.5, 7, 14, 2 - f, 1.2, sp.body);
  c.px(14, 1 - f, sp.trim.t4);

  if (hatch) {
    // 유충 기어 나오기 + 산란구 점액 분출
    c.partDome(15.5, 22 + f, 2.6, 2.0, makeRamp8(sp.bone.t3, sp.bone.t1, sp.white));
    c.px(14, 22 + f, sp.trim.t4);
    c.px(17, 22 + f, sp.trim.t4);
    c.stampMuzzleBlast(15.5, 26, 0, 1, f, 'CRIMSON');
  }
}

function drawQueen32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const { dx, dy } = dir8Vector(dir);
  const back = isBackDir(dir);
  const hx = Math.round(dx * 3);
  const boneRamp = makeRamp8(sp.bone.t3, sp.bone.t0, sp.white);
  const goldRamp = makeRamp8(sp.trim.t3, sp.trim.t0, sp.white);
  const legRamp = makeRamp8(sp.body.c3, sp.body.c0, sp.body.c6);
  const strike = anim === 'ATTACK';

  // 거대 산란 복부 (뒤쪽, 띠 마디)
  const ax = 15.5 - dx * 4;
  const ay = 21 - dy * 3;
  bugLegPairs(c, 15.5, 22, 3, 3, 6, 6, frame, anim, legRamp, sp.trim.t3, 1.4);
  c.partDome(ax, ay, 9.6, 7.2, sp.body, { trim: sp.trim, trimBottom: true });
  for (let k = -1; k <= 1; k += 1) {
    const by = Math.round(ay + k * 3);
    for (let x = Math.round(ax - 7 + Math.abs(k) * 1); x <= Math.round(ax + 7 - Math.abs(k)); x += 1) {
      if (c.isOpaque(x, by)) c.px(x, by, x < ax ? sp.body.c3 : sp.body.c2);
    }
  }
  c.px(ax - 3, ay - 4, sp.trim.t4);
  c.px(ax + 3, ay - 4, sp.trim.t2);

  // 낫 모양 앞다리 2쌍 (공격 시 앞으로 내리찍기)
  const scythe = (side: number): void => {
    const sx = 15.5 + side * 6;
    const raise = strike ? (f === 0 ? -1 : 2) : f;
    const ex = 15.5 + side * 12;
    const ey = strike ? 14 + dy * 6 : 4 + raise;
    c.partCapsule(sx, 13, ex, ey, 1.8, boneRamp);
    const tipX = ex - side * 3 + (strike ? dx * 4 : 0);
    const tipY = strike ? ey + 6 : ey + 8;
    c.partCapsule(ex, ey, tipX, tipY, 1.1, boneRamp);
    c.px(tipX, tipY + 1, sp.white);
  };

  // 흉부 + 머리
  const head = (): void => {
    const hy = 10 + Math.max(0, dy) * 2;
    c.partDome(15.5 + hx, hy, 5.6, 4.6, sp.body, { trim: sp.trim, trimBottom: true });
    // 금빛 왕관 가시 5개
    const crown: Array<[number, number]> = [[-4, 3], [-2, 5], [0, 6], [2, 5], [4, 3]];
    for (const [ox, h] of crown) {
      c.partCapsule(15.5 + hx + ox, hy - 3, 15.5 + hx + ox * 1.25, hy - 3 - h, 0.9, goldRamp);
    }
    if (!back) {
      glowEyes(c, 15.5 + hx, hy, 2.5, sp.trim.t4, f);
      c.px(15.5 + hx, hy - 2, sp.trim.t4);
      // 집게 턱 (공격 시 벌어짐)
      const open = strike ? 2 : 0;
      c.partCapsule(13.5 + hx - open, hy + 3, 12.5 + hx - open, hy + 7, 1.0, boneRamp);
      c.partCapsule(17.5 + hx + open, hy + 3, 18.5 + hx + open, hy + 7, 1.0, boneRamp);
    }
  };

  if (back) head();
  c.partDome(15.5 + dx, 15 - dy, 7.2, 5.0, sp.body, { trim: sp.trim, trimBottom: true });
  c.partDome(15.5 + dx, 13.5 - dy, 4.0, 2.2, makeRamp8(sp.body.c6, sp.body.c3, sp.white));
  scythe(-1);
  scythe(1);
  if (!back) head();

  if (strike) {
    c.stampClawSlash(16 + dx * 12, 18 + dy * 10, dx, dy, f, 'CRIMSON');
  }
}

function drawSpire32(
  c: SculptCanvas32,
  palette: FactionPalette,
  frame: number,
  _dir: SpriteDir8,
  anim: SpriteAnim
): void {
  const sp = buildStudioPalette(palette);
  const f = frame % 2;
  const burst = anim === 'ATTACK';
  const podRamp = makeRamp8(sp.trim.t3, sp.body.c2, [252, 255, 220]);
  const barkRamp = makeRamp8(sp.body.c4, sp.body.c0, sp.body.c7);

  // 뿌리
  const roots: Array<[number, number, number, number]> = [
    [11, 26, 3, 30],
    [13, 28, 9, 31],
    [18, 28, 22, 31],
    [20, 26, 28, 30],
  ];
  for (const [x0, y0, x1, y1] of roots) c.partCapsule(x0, y0, x1, y1, 1.7, barkRamp);

  // 테이퍼진 탑신: 아래가 넓은 마디 4단
  const tiers: Array<[number, number, number]> = [
    [26, 7.6, 3.4],
    [20.5, 6.2, 3.2],
    [15.5, 5.0, 3.0],
    [11, 4.0, 2.8],
  ];
  for (const [ty, rx, ry] of tiers) {
    c.partDome(15.5, ty, rx, ry, sp.body, { trim: sp.trim, trimBottom: true });
  }
  // 세로 갈비 홈
  for (let y = 9; y <= 27; y += 1) {
    if (c.isOpaque(13, y)) c.px(13, y, sp.body.c2);
    if (c.isOpaque(18, y)) c.px(18, y, sp.body.c1);
  }

  // 측면 포자 꼬투리 (교대로 박동)
  const pods: Array<[number, number, number]> = [
    [7, 23, 2.6],
    [24, 21, 2.6],
    [9, 16, 2.2],
    [22, 14, 2.2],
  ];
  pods.forEach(([px, py, r], i) => {
    const pulse = (i + frame) % 2 === 0 ? 0.35 : 0;
    c.partDome(px, py, r + pulse, r + pulse, podRamp, { trim: sp.trim, trimBottom: true });
    c.px(px - 1, py - 1, sp.white);
  });

  // 정수리 포자 구근 + 발광 개구부
  const crownR = burst ? 4.4 + f * 0.4 : 3.6 + f * 0.3;
  c.partDome(15.5, 5, crownR, crownR, podRamp, { trim: sp.trim, trimBottom: true });
  c.px(15, 5, burst ? sp.white : sp.trim.t4);
  c.px(16, 5, sp.trim.t4);
  c.px(15, 4, sp.white);
  for (const ox of [-3, 0, 3]) c.px(15.5 + ox, 5 - crownR, sp.trim.t4);

  if (burst) {
    // 포자 고리 방출
    c.fxBegin();
    const r = 8 + f * 2;
    for (let k = 0; k < 10; k += 1) {
      const a = (k / 10) * Math.PI * 2;
      const x = 15.5 + Math.cos(a) * r;
      const y = 6 + Math.sin(a) * r * 0.7;
      c.px(x, y, k % 2 === 0 ? sp.trim.t4 : [250, 255, 220]);
      c.px(x + 1, y, sp.trim.t2);
    }
    c.fxEnd();
  } else if (f === 1) {
    c.fxBegin();
    c.px(12, 0, sp.trim.t3);
    c.px(19, 1, sp.trim.t4);
    c.fxEnd();
  }
}

// ─────────────────────────── 스프라이트 시트 사양 ───────────────────────────
// 32x32 논리 프레임 · 스프라이트당 16색(외곽선 포함, 투명 제외) · IDLE 2 / WALK 4 / ATTACK 4
// 프레임별 얼굴·의상·크기·중심점·발 기준선 유지 · 여백·텍스트·그림자·안티앨리어싱 없음

export const SPRITE_FRAME_COUNT: Readonly<Record<SpriteAnim, number>> = { IDLE: 2, WALK: 4, ATTACK: 4 };
export const SPRITE_MAX_COLORS = 16;
/** 발 기준선: 모든 프레임·방향에서 가장 아래 불투명 픽셀이 이 행에 닿는다 */
export const SPRITE_BASELINE_Y = 31;
/** 중심점(피벗): 기준 프레임(IDLE 0)의 발 중심이 이 x 위치(15.5 = 16px 폭의 정중앙)에 온다 */
export const SPRITE_PIVOT_X = 15.5;
/** 이 행부터 아래는 하체(다리): 걷기 보폭·디딤발 처리 대상 */
const HIP_Y = 24;
/** 이 행부터 위는 머리·어깨: 공격 반동은 이 부분만 젖힌다 */
const SHOULDER_Y = 16;

type PixelBuf = Uint8ClampedArray;

interface FramePlan {
  drawAnim: SpriteAnim;
  drawFrame: number;
  fx: boolean;
  /** 상체(splitY 위쪽) 이동량 */
  upper: [number, number];
  splitY: number;
  legL: [number, number];
  legR: [number, number];
}

function dirUnit(dir: SpriteDir8): [number, number] {
  const { dx, dy } = dir8Vector(dir);
  return [dx > 0.3 ? 1 : dx < -0.3 ? -1 : 0, dy > 0.3 ? 1 : dy < -0.3 ? -1 : 0];
}

/**
 * 공용 애니메이터: 상태·프레임 번호를 드로잉 포즈 + 1px 관절 이동으로 바꾼다.
 * - IDLE 0 기본 / 1 숨쉬기(상체 1px 위)
 * - WALK 0 왼발 착지(보폭) / 1 지나가기(상체·오른발 들림) / 2 오른발 착지 / 3 지나가기(상체·왼발 들림)
 * - ATTACK 0 예비동작(상체를 조준 반대로 젖힘) / 1 발사(이펙트) / 2 반동(머리·어깨 젖힘) / 3 복귀(앞으로 1px 따라감)
 * 디딤발은 항상 기준선에 남아 있어 발 기준선이 흔들리지 않는다.
 */
function planFrame(anim: SpriteAnim, frame: number, dir: SpriteDir8): FramePlan {
  const n = SPRITE_FRAME_COUNT[anim];
  const f = ((Math.round(frame) % n) + n) % n;
  const [ux, uy] = dirUnit(dir);
  const base: FramePlan = { drawAnim: anim, drawFrame: f, fx: false, upper: [0, 0], splitY: HIP_Y, legL: [0, 0], legR: [0, 0] };
  if (anim === 'IDLE') {
    return { ...base, fx: true, upper: f === 1 ? [0, -1] : [0, 0] };
  }
  if (anim === 'WALK') {
    switch (f) {
      case 0:
        return { ...base, legL: [-1, 0] };
      case 1:
        return { ...base, upper: [0, -1], legR: [0, -1] };
      case 2:
        return { ...base, legR: [1, 0] };
      default:
        return { ...base, upper: [0, -1], legL: [0, -1] };
    }
  }
  switch (f) {
    case 0:
      return { ...base, drawFrame: 0, upper: [-ux, -uy] };
    case 1:
      return { ...base, drawFrame: 0, fx: true };
    case 2:
      return { ...base, drawFrame: 1, fx: true, upper: [-ux, -uy], splitY: SHOULDER_Y };
    default:
      return { ...base, drawFrame: 1, upper: [ux, uy] };
  }
}

/** 아키타입별 원본 드로잉 (몸 + 이펙트 레이어, 외곽선 후처리 전) */
function drawRaw(
  archetype: SpriteArchetype,
  palette: FactionPalette,
  f: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): SculptCanvas32 {
  const canvas = new SculptCanvas32();

  switch (archetype) {
    case 'COMMANDER': {
      const kind = detectCommanderFaction(palette);
      if (kind === 'HIVE') {
        drawHiveCommander32(canvas, palette, f, dir, anim);
      } else if (kind === 'LUMEN') {
        drawLumenCommander32(canvas, palette, f, dir, anim);
      } else {
        drawIroncladCommander32(canvas, palette, f, dir, anim);
      }
      break;
    }
    case 'SOLDIER':
      drawSoldier32(canvas, palette, f, dir, anim);
      break;
    case 'FLAMER':
      drawFlamer32(canvas, palette, f, dir, anim);
      break;
    case 'WALKER':
      drawWalker32(canvas, palette, f, dir, anim);
      break;
    case 'DRONE':
      drawDrone32(canvas, palette, f, dir, anim);
      break;
    case 'CLAW':
      drawClaw32(canvas, palette, f, dir, anim);
      break;
    case 'SPITTER':
      drawSpitter32(canvas, palette, f, dir, anim);
      break;
    case 'SPEWER':
      drawSpewer32(canvas, palette, f, dir, anim);
      break;
    case 'BEETLE':
      drawBeetle32(canvas, palette, f, dir, anim);
      break;
    case 'KNIGHT':
      drawKnight32(canvas, palette, f, dir, anim);
      break;
    case 'PRISM':
      drawPrism32(canvas, palette, f, dir, anim);
      break;
    case 'LANCER':
      drawLancer32(canvas, palette, f, dir, anim);
      break;
    case 'ORB':
      drawOrb32(canvas, palette, f, dir, anim);
      break;
    case 'MITE':
      drawMite32(canvas, palette, f, dir, anim);
      break;
    case 'CRAWLER':
      drawCrawler32(canvas, palette, f, dir, anim);
      break;
    case 'BLOATER':
      drawBloater32(canvas, palette, f, dir, anim);
      break;
    case 'BRUTE':
      drawBrute32(canvas, palette, f, dir, anim);
      break;
    case 'MATRON':
      drawMatron32(canvas, palette, f, dir, anim);
      break;
    case 'SNIPER':
      drawSniper32(canvas, palette, f, dir, anim);
      break;
    case 'SHIELDER':
      drawShielder32(canvas, palette, f, dir, anim);
      break;
    case 'SAPPER':
      drawSapper32(canvas, palette, f, dir, anim);
      break;
    case 'TESLA':
      drawTesla32(canvas, palette, f, dir, anim);
      break;
    case 'CHARGER':
      drawCharger32(canvas, palette, f, dir, anim);
      break;
    case 'SPORER':
      drawSporer32(canvas, palette, f, dir, anim);
      break;
    case 'SPLITTER':
      drawSplitter32(canvas, palette, f, dir, anim);
      break;
    case 'BOMBER':
      drawBomber32(canvas, palette, f, dir, anim);
      break;
    case 'SHELL':
      drawShell32(canvas, palette, f, dir, anim);
      break;
    case 'NEST':
      drawNest32(canvas, palette, f, dir, anim);
      break;
    case 'QUEEN':
      drawQueen32(canvas, palette, f, dir, anim);
      break;
    case 'SPIRE':
      drawSpire32(canvas, palette, f, dir, anim);
      break;
  }

  return canvas;
}

const isOutlinePx = (d: PixelBuf, i: number): boolean =>
  d[i] === OUTLINE_RGB[0] && d[i + 1] === OUTLINE_RGB[1] && d[i + 2] === OUTLINE_RGB[2];

function translateBuf(src: PixelBuf, ox: number, oy: number, size: number = SPRITE_SIZE): PixelBuf {
  const out = new Uint8ClampedArray(src.length);
  for (let y = 0; y < size; y += 1) {
    const sy = y - oy;
    if (sy < 0 || sy >= size) continue;
    for (let x = 0; x < size; x += 1) {
      const sx = x - ox;
      if (sx < 0 || sx >= size) continue;
      const si = (sy * size + sx) * 4;
      if (src[si + 3] === 0) continue;
      const di = (y * size + x) * 4;
      out[di] = src[si];
      out[di + 1] = src[si + 1];
      out[di + 2] = src[si + 2];
      out[di + 3] = 255;
    }
  }
  return out;
}

function bottomRow(d: PixelBuf): number {
  for (let y = SPRITE_SIZE - 1; y >= 0; y -= 1) {
    for (let x = 0; x < SPRITE_SIZE; x += 1) {
      if (d[(y * SPRITE_SIZE + x) * 4 + 3] > 0) return y;
    }
  }
  return SPRITE_BASELINE_Y;
}

/** 기준 프레임(IDLE 0)의 발 중심·바닥을 피벗·기준선에 맞추는 방향별 이동량 */
const pivotCache = new Map<string, [number, number]>();
function pivotOffset(archetype: SpriteArchetype, palette: FactionPalette, dir: SpriteDir8): [number, number] {
  const key = `${archetype}|${palette.primary}|${palette.secondary}|${palette.accent}|${dir}`;
  const hit = pivotCache.get(key);
  if (hit) return hit;
  const ref = drawRaw(archetype, palette, 0, dir, 'IDLE').body;
  const by = bottomRow(ref);
  let sum = 0;
  let cnt = 0;
  for (let y = Math.max(0, by - 3); y <= by; y += 1) {
    for (let x = 0; x < SPRITE_SIZE; x += 1) {
      if (ref[(y * SPRITE_SIZE + x) * 4 + 3] > 0) {
        sum += x;
        cnt += 1;
      }
    }
  }
  const cx = cnt > 0 ? sum / cnt : SPRITE_PIVOT_X;
  // 실루엣이 프레임 밖으로 잘리지 않는 범위 안에서만 피벗을 맞춘다
  let minX = SPRITE_SIZE;
  let maxX = -1;
  for (let i = 3; i < ref.length; i += 4) {
    if (ref[i] === 0) continue;
    const x = ((i - 3) / 4) % SPRITE_SIZE;
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
  }
  const want = Math.round(SPRITE_PIVOT_X - cx);
  const ox = maxX < 0 ? 0 : Math.max(-minX, Math.min(SPRITE_SIZE - 1 - maxX, want));
  const off: [number, number] = [ox, SPRITE_BASELINE_Y - by];
  pivotCache.set(key, off);
  return off;
}

/** 몸통 띠(10~23행) 불투명 픽셀 x의 중앙값 */
function torsoMedianX(d: PixelBuf): number {
  const xs: number[] = [];
  for (let y = 10; y <= 23; y += 1) {
    for (let x = 0; x < SPRITE_SIZE; x += 1) {
      if (d[(y * SPRITE_SIZE + x) * 4 + 3] > 0) xs.push(x);
    }
  }
  xs.sort((p2, q) => p2 - q);
  return xs.length ? xs[xs.length >> 1] : SPRITE_PIVOT_X;
}

/** 공격 포즈 원화의 몸통이 대기 포즈와 어긋나 있으면(원본 시트 드리프트) 대기 포즈 기준으로 맞춘다 */
const attackAlignCache = new Map<string, number>();
function attackAlignX(archetype: SpriteArchetype, palette: FactionPalette, dir: SpriteDir8): number {
  const key = `${archetype}|${palette.primary}|${palette.secondary}|${palette.accent}|${dir}`;
  const hit = attackAlignCache.get(key);
  if (hit !== undefined) return hit;
  const idle = torsoMedianX(drawRaw(archetype, palette, 0, dir, 'IDLE').body);
  const atk = torsoMedianX(drawRaw(archetype, palette, 0, dir, 'ATTACK').body);
  const v = Math.max(-3, Math.min(3, Math.round(idle - atk)));
  attackAlignCache.set(key, v);
  return v;
}

/**
 * 관절 이동: 상체는 원본 위에 덧칠(빈틈 대신 1px 늘어나 몸통이 끊기지 않음),
 * 다리는 원래 자리를 비우고 옮긴다(들어 올린 발이 바닥에 잔상으로 남지 않음).
 */
function applyPose(src: PixelBuf, plan: FramePlan): PixelBuf {
  const out = new Uint8ClampedArray(src);
  const moves: Array<{ ox: number; oy: number; clear: boolean; test: (x: number, y: number) => boolean }> = [
    { ox: plan.legL[0], oy: plan.legL[1], clear: true, test: (x, y) => y >= HIP_Y && x < 16 },
    { ox: plan.legR[0], oy: plan.legR[1], clear: true, test: (x, y) => y >= HIP_Y && x >= 16 },
    { ox: plan.upper[0], oy: plan.upper[1], clear: false, test: (_x, y) => y < plan.splitY },
  ];
  for (const mv of moves) {
    if (mv.ox === 0 && mv.oy === 0) continue;
    if (mv.clear) {
      for (let y = 0; y < SPRITE_SIZE; y += 1) {
        for (let x = 0; x < SPRITE_SIZE; x += 1) {
          if (mv.test(x, y)) out[(y * SPRITE_SIZE + x) * 4 + 3] = 0;
        }
      }
    }
    for (let y = 0; y < SPRITE_SIZE; y += 1) {
      for (let x = 0; x < SPRITE_SIZE; x += 1) {
        if (!mv.test(x, y)) continue;
        const si = (y * SPRITE_SIZE + x) * 4;
        if (src[si + 3] === 0) continue;
        const tx = x + mv.ox;
        const ty = y + mv.oy;
        if (tx < 0 || tx >= SPRITE_SIZE || ty < 0 || ty >= SPRITE_SIZE) continue;
        const di = (ty * SPRITE_SIZE + tx) * 4;
        out[di] = src[si];
        out[di + 1] = src[si + 1];
        out[di + 2] = src[si + 2];
        out[di + 3] = 255;
      }
    }
  }
  return out;
}

// ── 16색 양자화: 스프라이트(아키타입 × 팔레트)마다 전 방향·전 상태 공용 팔레트 1벌 ──

const colorDist = (a: Rgb, b: Rgb): number => {
  const rm = (a[0] + b[0]) / 2;
  const dr = a[0] - b[0];
  const dg = a[1] - b[1];
  const db = a[2] - b[2];
  return (2 + rm / 256) * dr * dr + 4 * dg * dg + (2 + (255 - rm) / 256) * db * db;
};

const spritePaletteCache = new Map<string, Rgb[]>();

/** 결정론적 메디안 컷 + k-means 다듬기로 외곽선 1 + 15색을 고른다 */
export function getSpritePalette16(archetype: SpriteArchetype, palette: FactionPalette): Rgb[] {
  const key = `${archetype}|${palette.primary}|${palette.secondary}|${palette.accent}`;
  const hit = spritePaletteCache.get(key);
  if (hit) return hit;
  const counts = new Map<number, number>();
  for (const dir of ALL_DIRS_8) {
    for (const [anim, fr] of [['IDLE', 0], ['IDLE', 1], ['WALK', 0], ['ATTACK', 0], ['ATTACK', 1]] as const) {
      const d = drawRaw(archetype, palette, fr, dir, anim).body;
      for (let i = 0; i < d.length; i += 4) {
        if (d[i + 3] === 0 || isOutlinePx(d, i)) continue;
        const k = (d[i] << 16) | (d[i + 1] << 8) | d[i + 2];
        counts.set(k, (counts.get(k) ?? 0) + 1);
      }
    }
  }
  const pts = [...counts.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([k, n]) => ({ c: [(k >> 16) & 255, (k >> 8) & 255, k & 255] as Rgb, w: Math.sqrt(n) }));
  const K = SPRITE_MAX_COLORS - 1;
  let centers: Rgb[];
  if (pts.length <= K) {
    centers = pts.map((p) => p.c);
  } else {
    // 메디안 컷: 가중 분산이 가장 큰 상자를 가장 긴 축으로 반분
    let boxes = [pts];
    while (boxes.length < K) {
      let bi = -1;
      let best = -1;
      let axis = 0;
      boxes.forEach((bx, i) => {
        if (bx.length < 2) return;
        for (let ch = 0; ch < 3; ch += 1) {
          let lo = 255;
          let hi = 0;
          for (const p of bx) {
            lo = Math.min(lo, p.c[ch]);
            hi = Math.max(hi, p.c[ch]);
          }
          const tot = bx.reduce((s2, p) => s2 + p.w, 0);
          const score = (hi - lo) * Math.sqrt(tot);
          if (score > best) {
            best = score;
            bi = i;
            axis = ch;
          }
        }
      });
      if (bi < 0) break;
      const bx = [...boxes[bi]].sort((p, q) => p.c[axis] - q.c[axis] || p.c[0] - q.c[0] || p.c[1] - q.c[1] || p.c[2] - q.c[2]);
      const half = bx.reduce((s2, p) => s2 + p.w, 0) / 2;
      let acc = 0;
      let cut = 1;
      for (; cut < bx.length - 1; cut += 1) {
        acc += bx[cut - 1].w;
        if (acc >= half) break;
      }
      boxes.splice(bi, 1, bx.slice(0, cut), bx.slice(cut));
    }
    const mean = (bx: typeof pts): Rgb => {
      const t = bx.reduce((s2, p) => s2 + p.w, 0) || 1;
      return [0, 1, 2].map((ch) => Math.round(bx.reduce((s2, p) => s2 + p.c[ch] * p.w, 0) / t)) as Rgb;
    };
    centers = boxes.map(mean);
    for (let it = 0; it < 4; it += 1) {
      const groups: (typeof pts)[] = centers.map(() => []);
      for (const p of pts) {
        let bi = 0;
        let bd = Infinity;
        centers.forEach((c2, i) => {
          const d2 = colorDist(p.c, c2);
          if (d2 < bd) {
            bd = d2;
            bi = i;
          }
        });
        groups[bi].push(p);
      }
      centers = centers.map((c2, i) => (groups[i].length ? mean(groups[i]) : c2));
    }
    // 가장 밝은 하이라이트는 평균에 묻히지 않도록 실제 최고 명도색으로 고정
    const lum = (c2: Rgb): number => c2[0] * 0.3 + c2[1] * 0.59 + c2[2] * 0.11;
    const brightest = pts.reduce((m2, p) => (lum(p.c) > lum(m2.c) ? p : m2), pts[0]).c;
    let ni = 0;
    centers.forEach((c2, i) => {
      if (colorDist(c2, brightest) < colorDist(centers[ni], brightest)) ni = i;
    });
    centers[ni] = brightest;
  }
  const pal: Rgb[] = [OUTLINE_RGB, ...centers];
  spritePaletteCache.set(key, pal);
  return pal;
}

function quantizeBuf(d: PixelBuf, pal: Rgb[]): void {
  const memo = new Map<number, Rgb>();
  for (let i = 0; i < d.length; i += 4) {
    if (d[i + 3] === 0) continue;
    if (isOutlinePx(d, i)) continue;
    const k = (d[i] << 16) | (d[i + 1] << 8) | d[i + 2];
    let c2 = memo.get(k);
    if (!c2) {
      const src: Rgb = [d[i], d[i + 1], d[i + 2]];
      let bd = Infinity;
      c2 = pal[1] ?? OUTLINE_RGB;
      for (let j = 1; j < pal.length; j += 1) {
        const dd = colorDist(src, pal[j]);
        if (dd < bd) {
          bd = dd;
          c2 = pal[j];
        }
      }
      memo.set(k, c2);
    }
    d[i] = c2[0];
    d[i + 1] = c2[1];
    d[i + 2] = c2[2];
    d[i + 3] = 255;
  }
}

/** 색 픽셀이 투명과 맞닿은 곳에만 1px 외곽선 (외곽선을 겹겹이 두껍게 만들지 않는다) */
function outlineBuf(d: PixelBuf, size: number = SPRITE_SIZE): void {
  const snap = new Uint8ClampedArray(d);
  const solid = (x: number, y: number): boolean => {
    if (x < 0 || y < 0 || x >= size || y >= size) return false;
    const i = (y * size + x) * 4;
    return snap[i + 3] > 0 && !isOutlinePx(snap, i);
  };
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const i = (y * size + x) * 4;
      if (snap[i + 3] > 0) continue;
      if (solid(x - 1, y) || solid(x + 1, y) || solid(x, y - 1) || solid(x, y + 1)) {
        d[i] = OUTLINE_RGB[0];
        d[i + 1] = OUTLINE_RGB[1];
        d[i + 2] = OUTLINE_RGB[2];
        d[i + 3] = 255;
      }
    }
  }
}

/**
 * 48x48 이펙트 레이어(fx) 외곽선 후처리:
 * 유닛 본체(body)가 투명한 바깥 영역에만 1px #070a10 외곽선을 둘러,
 * 총구/검신과 이펙트 사이에 검은 경계선이 생기지 않으면서 배경 타일 위에서 선명하게 돋보이게 한다.
 */
function outlineFxBuf(fx: PixelBuf, body: PixelBuf): void {
  const snap = new Uint8ClampedArray(fx);
  const solid = (x: number, y: number): boolean => {
    if (x < 0 || y < 0 || x >= SPRITE_FX_SIZE || y >= SPRITE_FX_SIZE) return false;
    const i = (y * SPRITE_FX_SIZE + x) * 4;
    return snap[i + 3] > 0 && !isOutlinePx(snap, i);
  };
  const bodyOpaque = (fxX: number, fxY: number): boolean => {
    const bx = fxX - SPRITE_FX_PAD;
    const by = fxY - SPRITE_FX_PAD;
    if (bx < 0 || by < 0 || bx >= SPRITE_SIZE || by >= SPRITE_SIZE) return false;
    return body[(by * SPRITE_SIZE + bx) * 4 + 3] > 0;
  };
  for (let y = 0; y < SPRITE_FX_SIZE; y += 1) {
    for (let x = 0; x < SPRITE_FX_SIZE; x += 1) {
      const i = (y * SPRITE_FX_SIZE + x) * 4;
      if (snap[i + 3] > 0 || bodyOpaque(x, y)) continue;
      if (solid(x - 1, y) || solid(x + 1, y) || solid(x, y - 1) || solid(x, y + 1)) {
        fx[i] = OUTLINE_RGB[0];
        fx[i + 1] = OUTLINE_RGB[1];
        fx[i + 2] = OUTLINE_RGB[2];
        fx[i + 3] = 255;
      }
    }
  }
}

/**
 * ATTACK 0(예비동작) 전용 차징·조준 광원(48x48 fx):
 * 실제 발사/타격(ATTACK 1) 직전에 총구 레이저·파일럿 불꽃·코일 코로나·포식자 안광을 1프레임 번쩍여 공격 템포와 가독성을 높인다.
 */
function buildWindupFx(
  archetype: SpriteArchetype,
  palette: FactionPalette,
  dir: SpriteDir8
): PixelBuf {
  const c = new SculptCanvas32();
  const { dx, dy } = dir8Vector(dir);
  const evolved = isEvolvedPalette(palette);
  const white: Rgb = [255, 255, 255];
  c.fxBegin();

  switch (archetype) {
    case 'SOLDIER':
    case 'COMMANDER': {
      const [mx, my] = RIFLE_MUZZLE_TIP[dir];
      const glow: Rgb = evolved ? [255, 207, 74] : hexToRgb(palette.accent);
      c.px(mx, my, white);
      for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
        c.px(mx + ox, my + oy, glow);
      }
      break;
    }
    case 'SNIPER': {
      // 저격 조준경 붉은 십자 섬광 + 총구 조준 레이저 도트
      const tx = 16 + dx * 15;
      const ty = 18 + dy * 13;
      const laser: Rgb = evolved ? [255, 56, 88] : [255, 96, 72];
      c.px(tx, ty, white);
      c.px(tx + dx * 3, ty + dy * 3, laser);
      c.px(tx + dx * 6, ty + dy * 6, laser);
      c.px(tx + dx * 9, ty + dy * 9, evolved ? [255, 207, 74] : laser);
      break;
    }
    case 'FLAMER': {
      // 화염 노즐 파일럿 점화 불꽃
      const nx = 16 + dx * 9;
      const ny = 18 + dy * 8;
      const col: Rgb = evolved ? [110, 238, 255] : [255, 168, 48];
      c.px(nx, ny, white);
      c.px(nx + dx, ny + dy, col);
      c.px(nx - dy, ny + dx, col);
      c.px(nx + dy, ny - dx, col);
      break;
    }
    case 'WALKER': {
      // 등면 박격포 발사관 점화 글로우
      const col: Rgb = evolved ? [255, 207, 74] : [255, 140, 42];
      if (dir === 'E' || dir === 'W') {
        const bx = dir === 'E' ? 6 : 25;
        c.px(bx, 2, white);
        c.px(bx, 1, col);
      } else {
        c.px(7, 2, white);
        c.px(24, 2, white);
        c.px(7, 1, col);
        c.px(24, 1, col);
      }
      break;
    }
    case 'TESLA': {
      // 코일 구체 과충전 코로나 링
      const back = isBackDir(dir);
      const s = sideSign(dir);
      const cx = back ? 15.5 : s > 0 ? 8 : s < 0 ? 23 : 7;
      const col: Rgb = evolved ? [208, 136, 255] : [95, 224, 255];
      for (let k = 0; k < 6; k += 1) {
        const a = (k / 6) * Math.PI * 2;
        c.px(cx + Math.cos(a) * 5, 4 + Math.sin(a) * 4, k % 2 === 0 ? white : col);
      }
      break;
    }
    case 'SHIELDER':
    case 'KNIGHT':
    case 'LANCER': {
      // 방패/창/검 선단 반사광 십자(+)
      const gx = 16 + dx * 10;
      const gy = 17 + dy * 8;
      const col: Rgb = evolved ? [255, 207, 74] : [95, 224, 255];
      c.px(gx, gy, white);
      for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
        c.px(gx + ox, gy + oy, col);
      }
      break;
    }
    default: {
      // 적/생체 유닛: 공격 직전 안광·턱 예고 스파크
      const gx = 16 + dx * 8;
      const gy = 18 + dy * 7;
      const acc = hexToRgb(palette.accent);
      c.px(gx, gy, white);
      c.px(gx + dx, gy + dy, acc);
      c.px(gx - dy * 2, gy + dx * 2, acc);
      c.px(gx + dy * 2, gy - dx * 2, acc);
      break;
    }
  }

  c.fxEnd();
  return c.fx;
}

interface SpriteFrameBufs {
  body: PixelBuf;
  fx: PixelBuf;
}

const frameMemo = new Map<string, SpriteFrameBufs>();

function composeFrame(
  archetype: SpriteArchetype,
  palette: FactionPalette,
  frame: number,
  dir: SpriteDir8,
  anim: SpriteAnim
): SpriteFrameBufs {
  const fMod = frame % SPRITE_FRAME_COUNT[anim];
  const plan = planFrame(anim, frame, dir);
  const key = `${archetype}|${palette.primary}|${palette.secondary}|${palette.accent}|${dir}|${anim}|${plan.drawFrame}|${fMod}`;
  const hit = frameMemo.get(key);
  if (hit) return hit;

  const raw = drawRaw(archetype, palette, plan.drawFrame, dir, plan.drawAnim);
  const [px0, oy] = pivotOffset(archetype, palette, dir);
  const ox = px0 + (plan.drawAnim === 'ATTACK' ? attackAlignX(archetype, palette, dir) : 0);
  let body = translateBuf(raw.body, ox, oy, SPRITE_SIZE);
  const isWindup = anim === 'ATTACK' && fMod === 0;
  const rawFx = isWindup ? buildWindupFx(archetype, palette, dir) : raw.fx;
  let fx =
    plan.fx || isWindup
      ? translateBuf(rawFx, ox + (isWindup ? plan.upper[0] : 0), oy + (isWindup ? plan.upper[1] : 0), SPRITE_FX_SIZE)
      : new Uint8ClampedArray(raw.fx.length);
  body = applyPose(body, plan);
  quantizeBuf(body, getSpritePalette16(archetype, palette));
  outlineBuf(body, SPRITE_SIZE);
  const snap = SPRITE_BASELINE_Y - bottomRow(body);
  if (snap !== 0) {
    body = translateBuf(body, 0, snap, SPRITE_SIZE);
    fx = translateBuf(fx, 0, snap, SPRITE_FX_SIZE);
  }
  if (plan.fx || isWindup) {
    outlineFxBuf(fx, body);
  }
  const out = { body, fx };
  if (frameMemo.size > 512) frameMemo.clear();
  frameMemo.set(key, out);
  return out;
}

/**
 * 순수 함수: 아키타입 + 팔레트 + 프레임 + 8방향 + 상태 → 32x32 RGBA 몸 프레임 (스프라이트 시트 사양 준수).
 * 프레임 번호는 상태별 프레임 수(IDLE 2 / WALK 4 / ATTACK 4)로 순환한다.
 */
export function renderSpritePixels(
  archetype: SpriteArchetype,
  palette: FactionPalette,
  frame: number = 0,
  dir: SpriteDir8 = 'S',
  anim: SpriteAnim = 'IDLE'
): { width: number; height: number; data: Uint8ClampedArray } {
  const { body } = composeFrame(archetype, palette, Math.abs(Math.round(frame)), dir, anim);
  return { width: SPRITE_SIZE, height: SPRITE_SIZE, data: new Uint8ClampedArray(body) };
}

/** 같은 프레임의 48x48 확장 이펙트 레이어 (총구 섬광·참격·번개·예비동작 안광 등). 비어 있으면 null */
export function renderSpriteFxPixels(
  archetype: SpriteArchetype,
  palette: FactionPalette,
  frame: number = 0,
  dir: SpriteDir8 = 'S',
  anim: SpriteAnim = 'IDLE'
): { width: number; height: number; data: Uint8ClampedArray } | null {
  const { fx } = composeFrame(archetype, palette, Math.abs(Math.round(frame)), dir, anim);
  for (let i = 3; i < fx.length; i += 4) {
    if (fx[i] > 0) return { width: SPRITE_FX_SIZE, height: SPRITE_FX_SIZE, data: new Uint8ClampedArray(fx) };
  }
  return null;
}

/** 시트 열 순서: IDLE 2 → WALK 4 → ATTACK 4 (행 = ALL_DIRS_8 순서) */
export const SPRITE_SHEET_COLUMNS: ReadonlyArray<{ anim: SpriteAnim; frame: number }> = (['IDLE', 'WALK', 'ATTACK'] as const).flatMap(
  (anim) => Array.from({ length: SPRITE_FRAME_COUNT[anim] }, (_, frame) => ({ anim, frame }))
);

/**
 * 여백·간격 없는 스프라이트 시트 (몸 레이어만, 그림자·텍스트 없음).
 * 크기 = (열 10 × 32) × (방향 8 × 32) = 320 × 256, 피벗 (16, 31).
 */
export function renderSpriteSheet(
  archetype: SpriteArchetype,
  palette: FactionPalette
): { width: number; height: number; data: Uint8ClampedArray; pivot: { x: number; y: number }; palette: Rgb[] } {
  const cols = SPRITE_SHEET_COLUMNS.length;
  const width = cols * SPRITE_SIZE;
  const height = ALL_DIRS_8.length * SPRITE_SIZE;
  const data = new Uint8ClampedArray(width * height * 4);
  ALL_DIRS_8.forEach((dir, row) => {
    SPRITE_SHEET_COLUMNS.forEach(({ anim, frame }, col) => {
      const fr = renderSpritePixels(archetype, palette, frame, dir, anim).data;
      for (let y = 0; y < SPRITE_SIZE; y += 1) {
        const di = ((row * SPRITE_SIZE + y) * width + col * SPRITE_SIZE) * 4;
        data.set(fr.subarray(y * SPRITE_SIZE * 4, (y + 1) * SPRITE_SIZE * 4), di);
      }
    });
  });
  return { width, height, data, pivot: { x: 16, y: SPRITE_BASELINE_Y }, palette: getSpritePalette16(archetype, palette) };
}

/**
 * 포탑 공병이 설치하는 센트리 포탑 (32x32, 발 기준선 31).
 * 삼각 지지대 + 받침 + 8방향 회전 포탑 머리. 진화형은 금장 쌍열 중포탑 + 탄약 드럼.
 */
export function renderTurretPixels(
  palette: FactionPalette,
  dir: SpriteDir8,
  evolved: boolean,
  firing: boolean
): { width: number; height: number; data: Uint8ClampedArray } {
  const c = new SculptCanvas32();
  const sp = buildStudioPalette(palette);
  const metal = makeRamp8(sp.metal.t3, sp.metal.t0, sp.white);
  const dark = makeRamp8(sp.metal.t2, sp.metal.t0, sp.metal.t4);
  const { dx, dy } = dir8Vector(dir);
  // 삼각 지지대
  c.partCapsule(15.5, 24, 8, 30, 1.2, dark);
  c.partCapsule(15.5, 24, 23, 30, 1.2, dark);
  c.partCapsule(15.5, 24, 15.5, 30.5, 1.2, metal);
  // 받침 + 회전축
  c.partDome(15.5, 24, evolved ? 6 : 5, 2.6, sp.body, { trim: sp.trim, trimBottom: true });
  const hx = 15.5;
  const hy = evolved ? 17 : 18;
  const back = dy < -0.3;
  const len = evolved ? 11 : 9;
  const offsets = evolved ? [-1.6, 1.6] : [0];
  const barrels = (): void => {
    for (const o of offsets) {
      const ox = -dy * o;
      const oy = dx * o * 0.7;
      const tx = hx + ox + dx * len;
      const ty = hy + oy + dy * len * 0.7;
      c.partCapsule(hx + ox, hy + oy, tx, ty, evolved ? 1.3 : 1.05, metal);
      c.px(tx, ty, evolved ? sp.trim.t4 : sp.metal.t4);
    }
  };
  if (back) barrels();
  c.partDome(hx, hy, evolved ? 6.2 : 5.2, evolved ? 4.6 : 4.0, evolved ? makeRamp8(sp.trim.t3, sp.trim.t0, sp.white) : sp.body, {
    trim: sp.trim,
    trimBottom: true,
  });
  // 조준 센서
  if (!back) {
    const ex = hx + dx * 2.5;
    const ey = hy - 1 + dy;
    c.px(ex, ey, evolved ? [255, 215, 74] : sp.eyeGlow);
    c.px(ex + 1, ey, sp.white);
    c.px(ex, ey + 1, OUTLINE_RGB);
  }
  if (evolved) {
    // 측면 탄약 드럼
    const side = dx >= 0 ? -1 : 1;
    c.partDome(hx + side * 6, hy + 2, 2.4, 2.4, dark, { trim: sp.trim, trimBottom: true });
  }
  if (!back) barrels();
  const out = new Uint8ClampedArray(c.body);
  outlineBuf(out);
  if (firing) {
    // 총구 섬광 (외곽선 바깥에 덧그림)
    for (const o of offsets) {
      const fx = Math.round(hx - dy * o + dx * (len + 2));
      const fy = Math.round(hy + dx * o * 0.7 + dy * (len + 2) * 0.7);
      const put = (x: number, y: number, col: Rgb): void => {
        if (x < 0 || y < 0 || x >= SPRITE_SIZE || y >= SPRITE_SIZE) return;
        const i = (y * SPRITE_SIZE + x) * 4;
        out[i] = col[0];
        out[i + 1] = col[1];
        out[i + 2] = col[2];
        out[i + 3] = 255;
      };
      put(fx, fy, [255, 255, 255]);
      put(fx + 1, fy, [255, 230, 140]);
      put(fx - 1, fy, [255, 230, 140]);
      put(fx, fy + 1, [255, 170, 60]);
      put(fx, fy - 1, [255, 170, 60]);
    }
  }
  return { width: SPRITE_SIZE, height: SPRITE_SIZE, data: out };
}

/** 하위 호환용 ASCII 실루엣 맵 추출기 */
export function getSpriteMap(archetype: SpriteArchetype): readonly string[] {
  const buf = renderSpritePixels(archetype, {
    primary: '#4f7fb8',
    secondary: '#2d4a6e',
    accent: '#f2c14e',
  });
  const rows: string[] = [];
  for (let y = 0; y < buf.height; y += 1) {
    let row = '';
    for (let x = 0; x < buf.width; x += 1) {
      const i = (y * buf.width + x) * 4;
      if (buf.data[i + 3] === 0) {
        row += '.';
      } else if (
        buf.data[i] === OUTLINE_RGB[0] &&
        buf.data[i + 1] === OUTLINE_RGB[1] &&
        buf.data[i + 2] === OUTLINE_RGB[2]
      ) {
        row += 'o';
      } else {
        row += 'p';
      }
    }
    rows.push(row);
  }
  return rows;
}

export function renderGemPixels(
  tier: 1 | 2 | 3,
  frame: number = 0
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 11;
  const data = new Uint8ClampedArray(size * size * 4);
  const f = Math.abs(Math.round(frame)) % 2;

  const setPx = (x: number, y: number, c: Rgb): void => {
    if (x < 0 || x >= size || y < 0 || y >= size) {
      return;
    }
    const i = (y * size + x) * 4;
    data[i] = c[0];
    data[i + 1] = c[1];
    data[i + 2] = c[2];
    data[i + 3] = 255;
  };

  const base: Rgb =
    tier === 3 ? [242, 172, 58] : tier === 2 ? [64, 224, 130] : [78, 212, 242];
  const dark: Rgb =
    tier === 3 ? [118, 58, 16] : tier === 2 ? [22, 92, 54] : [24, 78, 108];
  const light: Rgb = lighten(base, 0.42);
  const white: Rgb = [248, 252, 255];

  const radius = tier === 3 ? 4 : tier === 2 ? 3 : 2;
  const cx = 5;
  const cy = 5;

  for (let dy = -radius; dy <= radius; dy += 1) {
    const span = radius - Math.abs(dy);
    for (let dx = -span; dx <= span; dx += 1) {
      let col = base;
      if (dx < 0 && dy <= 0) {
        col = light;
      } else if (dx > 0 && dy >= 0) {
        col = dark;
      }
      setPx(cx + dx, cy + dy, col);
    }
  }
  setPx(cx, cy, white);
  setPx(cx - 1, cy - 1, white);
  if (tier >= 2) {
    setPx(cx, cy - 1, light);
    setPx(cx - 1, cy, light);
  }

  const snap = new Uint8ClampedArray(data);
  const isOp = (x: number, y: number): boolean =>
    x >= 0 && x < size && y >= 0 && y < size && snap[(y * size + x) * 4 + 3] > 0;
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      if (isOp(x, y)) {
        continue;
      }
      if (isOp(x - 1, y) || isOp(x + 1, y) || isOp(x, y - 1) || isOp(x, y + 1)) {
        setPx(x, y, OUTLINE_RGB);
      }
    }
  }

  if (f === 0) {
    setPx(cx - radius, cy - radius + 1, white);
  } else {
    setPx(cx + radius, cy - radius + 1, white);
    if (tier === 3) {
      setPx(cx, cy - radius - 1, white);
    }
  }

  return { width: size, height: size, data };
}

export function renderGroundTilePixels(): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 64;
  const data = new Uint8ClampedArray(size * size * 4);
  const baseDark: Rgb = [14, 18, 26];
  const baseMid: Rgb = [18, 24, 34];
  const baseLight: Rgb = [23, 30, 42];
  const plateDark: Rgb = [20, 27, 39];
  const plateLight: Rgb = [28, 37, 52];
  const seam: Rgb = [10, 13, 20];

  const setPx = (x: number, y: number, c: Rgb): void => {
    const wx = ((x % size) + size) % size;
    const wy = ((y % size) + size) % size;
    const i = (wy * size + wx) * 4;
    data[i] = c[0];
    data[i + 1] = c[1];
    data[i + 2] = c[2];
    data[i + 3] = 255;
  };

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const wave =
        Math.sin((x + y) * ((Math.PI * 2) / 32)) * 0.25 +
        Math.cos((x - y * 2) * ((Math.PI * 2) / 64)) * 0.2;
      const col = wave < -0.1 ? baseDark : wave > 0.14 ? baseLight : baseMid;
      setPx(x, y, col);
    }
  }

  for (let py = 6; py < 22; py += 1) {
    for (let px = 8; px < 24; px += 1) {
      if (px === 8 || py === 6) {
        setPx(px, py, plateLight);
      } else if (px === 23 || py === 21) {
        setPx(px, py, seam);
      } else if ((px + py) % 4 === 0) {
        setPx(px, py, plateLight);
      } else {
        setPx(px, py, plateDark);
      }
    }
  }
  setPx(10, 8, [40, 52, 72]);
  setPx(21, 8, [40, 52, 72]);
  setPx(10, 19, [40, 52, 72]);
  setPx(21, 19, [40, 52, 72]);

  const craters = [
    { cx: 44, cy: 18, r: 4 },
    { cx: 26, cy: 46, r: 5 },
  ];
  for (const cr of craters) {
    for (let dy = -cr.r; dy <= cr.r; dy += 1) {
      for (let dx = -cr.r; dx <= cr.r; dx += 1) {
        const d = Math.hypot(dx, dy);
        if (d <= cr.r - 1.2) {
          setPx(cr.cx + dx, cr.cy + dy, seam);
        } else if (d <= cr.r + 0.3) {
          setPx(cr.cx + dx, cr.cy + dy, dx + dy < 0 ? seam : plateLight);
        }
      }
    }
  }

  for (let g = 0; g < size; g += 4) {
    setPx(g, 0, plateDark);
    setPx(0, g, plateDark);
  }

  return { width: size, height: size, data };
}

// ─────────────────────────── 6. 월드 전투 이펙트 & 투사체 전용 픽셀아트 스프라이트 생성기 ───────────────────────────

const FX_BAYER_4X4: ReadonlyArray<ReadonlyArray<number>> = [
  [0, 8, 2, 10],
  [12, 4, 14, 6],
  [3, 11, 1, 9],
  [15, 7, 13, 5],
];

function makePixelCanvas(size: number): {
  data: Uint8ClampedArray;
  px: (x: number, y: number, c: Rgb) => void;
  disc: (cx: number, cy: number, r: number, c: Rgb, ditherKeep?: number) => void;
  outline: () => void;
} {
  const data = new Uint8ClampedArray(size * size * 4);
  const px = (x: number, y: number, c: Rgb): void => {
    const ix = Math.round(x);
    const iy = Math.round(y);
    if (ix < 0 || ix >= size || iy < 0 || iy >= size) return;
    const i = (iy * size + ix) * 4;
    data[i] = c[0];
    data[i + 1] = c[1];
    data[i + 2] = c[2];
    data[i + 3] = 255;
  };
  const disc = (cx: number, cy: number, r: number, c: Rgb, ditherKeep: number = 16): void => {
    const x0 = Math.floor(cx - r);
    const x1 = Math.ceil(cx + r);
    const y0 = Math.floor(cy - r);
    const y1 = Math.ceil(cy + r);
    const r2 = r * r;
    for (let y = y0; y <= y1; y += 1) {
      for (let x = x0; x <= x1; x += 1) {
        if ((x - cx) ** 2 + (y - cy) ** 2 > r2) continue;
        if (ditherKeep < 16 && FX_BAYER_4X4[y & 3][x & 3] >= ditherKeep) continue;
        px(x, y, c);
      }
    }
  };
  const outline = (): void => {
    outlineBuf(data, size);
  };
  return { data, px, disc, outline };
}

export type ExplosionVariant = 'STANDARD' | 'PLASMA' | 'ACID';
export const EXPLOSION_FRAME_COUNT = 5;

/**
 * 5프레임 28x28 볼륨 클러스터 폭발 픽셀 스프라이트 (박격포·다연장·포탑 유탄·자폭충):
 * - F0: 백열 십자 코어 섬광 + 초기 화구
 * - F1: 다중 볼륨 화구 클러스터 팽창
 * - F2: 최대 화구 + 외곽 충격파 도트 + 불똥 파편
 * - F3: 중심이 비어가는 도넛형 연기·잔열 고리 (Bayer 디더링)
 * - F4: 흩어지는 그을음 연기 클러스터
 */
export function renderExplosionFramePixels(
  frame: number,
  variant: ExplosionVariant = 'STANDARD'
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 28;
  const f = Math.max(0, Math.min(EXPLOSION_FRAME_COUNT - 1, Math.round(frame)));
  const c = makePixelCanvas(size);
  const cx = 13.5;
  const cy = 13.5;

  const white: Rgb = [255, 255, 255];
  const hot: Rgb =
    variant === 'PLASMA' ? [210, 254, 255] : variant === 'ACID' ? [242, 255, 175] : [255, 244, 148];
  const mid: Rgb =
    variant === 'PLASMA' ? [95, 224, 255] : variant === 'ACID' ? [168, 232, 56] : [255, 164, 42];
  const deep: Rgb =
    variant === 'PLASMA' ? [255, 207, 74] : variant === 'ACID' ? [74, 148, 24] : [216, 62, 28];
  const smoke: Rgb =
    variant === 'PLASMA' ? [48, 72, 108] : variant === 'ACID' ? [38, 62, 28] : [68, 44, 46];
  const darkSmoke: Rgb = [34, 26, 32];

  const lobes: ReadonlyArray<readonly [number, number, number]> = [
    [0, -1, 1.0],
    [-0.85, -0.45, 0.85],
    [0.85, -0.4, 0.85],
    [-0.7, 0.7, 0.8],
    [0.75, 0.65, 0.82],
    [0, 0.85, 0.76],
  ];

  if (f === 0) {
    c.disc(cx, cy, 6.2, deep);
    c.disc(cx, cy, 4.6, mid);
    c.disc(cx, cy, 3.0, hot);
    // 십자 섬광 광선
    for (let k = -9; k <= 9; k += 1) {
      c.px(cx + k, cy, Math.abs(k) <= 5 ? white : hot);
      c.px(cx, cy + k, Math.abs(k) <= 5 ? white : hot);
    }
    for (let k = -5; k <= 5; k += 1) {
      c.px(cx + k, cy + k, Math.abs(k) <= 2 ? white : hot);
      c.px(cx + k, cy - k, Math.abs(k) <= 2 ? white : hot);
    }
  } else if (f === 1) {
    for (const [lx, ly, sc] of lobes) {
      c.disc(cx + lx * 4.2, cy + ly * 4.2, 4.6 * sc, deep);
    }
    for (const [lx, ly, sc] of lobes) {
      c.disc(cx + lx * 3.2, cy + ly * 3.2, 3.6 * sc, mid);
    }
    c.disc(cx - 0.5, cy - 0.5, 4.2, hot);
    c.disc(cx - 1, cy - 1, 2.2, white);
  } else if (f === 2) {
    c.disc(cx, cy, 10.2, smoke, 12);
    for (const [lx, ly, sc] of lobes) {
      c.disc(cx + lx * 6.0, cy + ly * 6.0, 4.8 * sc, deep);
      c.disc(cx + lx * 5.2 - 0.5, cy + ly * 5.2 - 0.5, 3.3 * sc, mid);
    }
    c.disc(cx, cy, 4.4, hot, 13);
    c.disc(cx - 1, cy - 1, 2.0, white);
    // 외곽 불똥 스파크 8개
    for (let k = 0; k < 8; k += 1) {
      const a = (k / 8) * Math.PI * 2 + 0.25;
      c.px(cx + Math.cos(a) * 11.5, cy + Math.sin(a) * 11.5, k % 2 === 0 ? white : hot);
    }
  } else if (f === 3) {
    // 도넛형 연기·잔열 고리 (중심 공동화)
    for (let k = 0; k < 8; k += 1) {
      const a = (k / 8) * Math.PI * 2 + 0.2;
      const rx = cx + Math.cos(a) * 7.4;
      const ry = cy + Math.sin(a) * 7.4;
      c.disc(rx, ry, 3.8, smoke, 13);
      c.disc(rx - Math.cos(a) * 1.1, ry - Math.sin(a) * 1.1, 2.3, k % 2 === 0 ? deep : mid, 12);
      if (k % 2 === 0) {
        c.px(rx - Math.cos(a) * 1.5, ry - Math.sin(a) * 1.5, hot);
      }
    }
  } else {
    // 디더링 소멸 연기 퍼프
    for (let k = 0; k < 6; k += 1) {
      const a = (k / 6) * Math.PI * 2 + 0.5;
      const rx = cx + Math.cos(a) * 8.6;
      const ry = cy + Math.sin(a) * 8.6;
      c.disc(rx, ry, 2.8, darkSmoke, 9);
      c.disc(rx - 0.5, ry - 0.5, 1.8, smoke, 10);
      if (k % 2 === 0) {
        c.px(rx, ry, deep);
      }
    }
  }

  c.outline();
  return { width: size, height: size, data: c.data };
}

export type SlashVariant = 'BLADE' | 'BASH' | 'GOLD_BASH' | 'CLAW';
export const SLASH_FRAME_COUNT = 3;

/**
 * 3프레임 24x24 8방향 근접 참격(`BLADE` / `CLAW`) 및 방패 강타(`BASH` / `GOLD_BASH`) 픽셀 스프라이트.
 */
export function renderSlashFramePixels(
  frame: number,
  dir: SpriteDir8,
  variant: SlashVariant = 'BLADE'
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 24;
  const f = Math.max(0, Math.min(SLASH_FRAME_COUNT - 1, Math.round(frame)));
  const c = makePixelCanvas(size);
  const { dx, dy } = dir8Vector(dir);
  const perpX = -dy;
  const perpY = dx;
  const cx = 11.5;
  const cy = 11.5;

  const white: Rgb = [255, 255, 255];
  const main: Rgb =
    variant === 'GOLD_BASH'
      ? [255, 207, 74]
      : variant === 'CLAW'
        ? [184, 238, 64]
        : [110, 238, 255];
  const deep: Rgb =
    variant === 'GOLD_BASH'
      ? [216, 118, 24]
      : variant === 'CLAW'
        ? [74, 152, 24]
        : [32, 136, 204];

  if (variant === 'BASH' || variant === 'GOLD_BASH') {
    // 묵직한 타워 실드 이중 충격파 아크 + 파쇄 블록
    const push = f * 1.5;
    for (let u = -7; u <= 7; u += 1) {
      if (f === 2 && Math.abs(u) % 2 === 1) continue;
      const curve = (1 - (u / 7.5) ** 2) * 4.2 + push - 1.5;
      const ax = cx + perpX * u + dx * curve;
      const ay = cy + perpY * u + dy * curve;
      c.px(ax + dx, ay + dy, f === 0 || Math.abs(u) <= 3 ? white : main);
      c.px(ax, ay, main);
      if (f <= 1) {
        c.px(ax - dx, ay - dy, deep);
      }
      // 후방 2차 잔향 고리
      if (f >= 1 && Math.abs(u) <= 5) {
        c.px(ax - dx * 3, ay - dy * 3, deep);
      }
    }
    for (const k of [-4, -1.5, 1.5, 4]) {
      const r = 4.5 + f * 2.2;
      c.px(cx + perpX * k * 1.3 + dx * r, cy + perpY * k * 1.3 + dy * r, f === 0 ? white : main);
    }
  } else {
    // 초승달 검기 아크 (F0: 선단 집중 -> F1: 풀 스윙 호 -> F2: 디더링 잔상 & 스파크)
    for (let i = -8; i <= 8; i += 1) {
      const u = i / 8;
      if (f === 0 && u > 0.55) continue;
      if (f === 2 && (u < -0.45 || Math.abs(i) % 2 === 1)) continue;
      const curve = (1 - u * u) * 5.5 + f * 1.0 - 1.5;
      const sx = cx + perpX * u * 8.5 + dx * curve;
      const sy = cy + perpY * u * 8.5 + dy * curve;
      c.px(sx + dx, sy + dy, Math.abs(u) < 0.5 ? white : main);
      c.px(sx, sy, main);
      if (Math.abs(u) < 0.65 && f !== 2) {
        c.px(sx - dx, sy - dy, deep);
      }
    }
    for (let k = -1; k <= 2; k += 1) {
      const spA = Math.atan2(dy, dx) + k * 0.42;
      const spR = 4 + f * 2.6;
      c.px(cx + Math.cos(spA) * spR, cy + Math.sin(spA) * spR, k === 0 ? white : main);
    }
  }

  c.outline();
  return { width: size, height: size, data: c.data };
}

export type FlameVariant = 'FIRE' | 'PLASMA' | 'ACID';
export const FLAME_FRAME_COUNT = 4;

/**
 * 4프레임 14x14 볼륨 화염·플라즈마·산성 클러스터 퍼프 스프라이트 (`CONE` 방사 및 바닥 장판용).
 */
export function renderFlamePuffPixels(
  frame: number,
  variant: FlameVariant = 'FIRE'
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 14;
  const f = Math.max(0, Math.min(FLAME_FRAME_COUNT - 1, Math.round(frame)));
  const c = makePixelCanvas(size);
  const cx = 6.5;
  const cy = 6.5;

  const white: Rgb = [255, 255, 255];
  const bright: Rgb =
    variant === 'PLASMA' ? [210, 254, 255] : variant === 'ACID' ? [238, 255, 165] : [255, 236, 104];
  const mid: Rgb =
    variant === 'PLASMA' ? [95, 224, 255] : variant === 'ACID' ? [156, 228, 52] : [255, 132, 28];
  const outer: Rgb =
    variant === 'PLASMA' ? [255, 207, 74] : variant === 'ACID' ? [68, 142, 22] : [208, 42, 24];
  const smoke: Rgb =
    variant === 'PLASMA' ? [42, 74, 118] : variant === 'ACID' ? [34, 62, 22] : [64, 40, 42];

  if (f === 0) {
    c.disc(cx, cy, 3.2, mid);
    c.disc(cx - 0.4, cy - 0.4, 2.2, bright);
    c.disc(cx - 0.5, cy - 0.5, 1.2, white);
  } else if (f === 1) {
    c.disc(cx, cy, 4.4, outer);
    c.disc(cx - 0.5, cy - 0.5, 3.2, mid);
    c.disc(cx - 0.8, cy - 0.8, 2.0, bright);
    c.px(cx - 1, cy - 1, white);
  } else if (f === 2) {
    c.disc(cx + 0.5, cy + 0.5, 4.6, smoke, 13);
    c.disc(cx - 0.4, cy - 0.4, 3.8, outer);
    c.disc(cx - 0.8, cy - 0.8, 2.4, mid);
    c.px(cx - 1, cy - 1, bright);
  } else {
    c.disc(cx, cy, 4.2, smoke, 10);
    c.disc(cx - 0.5, cy - 0.5, 2.6, outer, 12);
    c.px(cx - 1, cy - 1, mid);
  }

  c.outline();
  return { width: size, height: size, data: c.data };
}

export type HitSparkVariant = 'SPARK' | 'PIERCE' | 'DEFLECT' | 'EXECUTE' | 'REFLECT';
export const HIT_SPARK_FRAME_COUNT = 3;

/**
 * 3프레임 16x16 피격·관통·도탄·처형·반사 픽셀 임팩트 스프라이트.
 */
export function renderHitSparkPixels(
  frame: number,
  dir: SpriteDir8,
  variant: HitSparkVariant = 'SPARK'
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 16;
  const f = Math.max(0, Math.min(HIT_SPARK_FRAME_COUNT - 1, Math.round(frame)));
  const c = makePixelCanvas(size);
  const { dx, dy } = dir8Vector(dir);
  const perpX = -dy;
  const perpY = dx;
  const cx = 7.5;
  const cy = 7.5;
  const white: Rgb = [255, 255, 255];

  if (variant === 'EXECUTE') {
    // 처형자 빈사 즉사: 진홍·황금 X자 단두대 교차 섬광
    const crimson: Rgb = [255, 56, 88];
    const gold: Rgb = [255, 207, 74];
    const span = f === 0 ? 6 : f === 1 ? 7 : 5;
    for (let k = -span; k <= span; k += 1) {
      if (f === 2 && Math.abs(k) < 2) continue;
      c.px(cx + k, cy + k, Math.abs(k) <= 2 ? white : gold);
      c.px(cx + k, cy - k, Math.abs(k) <= 2 ? white : crimson);
      if (Math.abs(k) <= 4 && f <= 1) {
        c.px(cx + k + 1, cy + k, crimson);
        c.px(cx + k - 1, cy - k, gold);
      }
    }
  } else if (variant === 'REFLECT') {
    // 성벽 분대 피해 반사: 황금 육각 방패 카운터 충격파
    const gold: Rgb = [255, 207, 74];
    const amber: Rgb = [235, 132, 32];
    const r = 3 + f * 1.8;
    for (let k = 0; k < 12; k += 1) {
      const a = (k / 12) * Math.PI * 2;
      c.px(cx + Math.cos(a) * r, cy + Math.sin(a) * r, k % 2 === 0 ? white : gold);
      if (f <= 1) {
        c.px(cx + Math.cos(a) * (r - 1), cy + Math.sin(a) * (r - 1), amber);
      }
    }
    if (f === 0) c.px(cx, cy, white);
  } else if (variant === 'DEFLECT') {
    // 갑각충 정면 70% 도탄: 은회색 V자 튕김 아크
    const silver: Rgb = [208, 224, 242];
    const steel: Rgb = [120, 138, 162];
    for (const side of [-1, 1]) {
      for (let s = 1; s <= 4; s += 1) {
        const px = cx + (dx * 0.7 + perpX * side * 0.8) * (s + f);
        const py = cy + (dy * 0.7 + perpY * side * 0.8) * (s + f);
        c.px(px, py, s <= 2 ? white : silver);
      }
    }
    if (f <= 1) {
      c.px(cx, cy, white);
      c.px(cx + dx, cy + dy, steel);
    }
  } else if (variant === 'PIERCE') {
    // 저격 / 관통탄 탄착: 전방 관통 다이아몬드 파열 + 충격 링
    const gold: Rgb = [255, 224, 104];
    const crimson: Rgb = [255, 72, 88];
    for (let s = -3; s <= 5; s += 1) {
      if (f === 2 && Math.abs(s) < 2) continue;
      c.px(cx + dx * s, cy + dy * s, Math.abs(s) <= 2 ? white : gold);
    }
    for (const side of [-1, 1]) {
      const w = 2 + f;
      c.px(cx + perpX * side * w, cy + perpY * side * w, f === 0 ? white : crimson);
      c.px(cx + dx * 2 + perpX * side * (w + 1), cy + dy * 2 + perpY * side * (w + 1), gold);
    }
  } else {
    // 일반 연사 탄착(SPARK): 가독성을 해치지 않는 간결한 3갈래 픽셀 스파크
    const yellow: Rgb = [255, 232, 112];
    const orange: Rgb = [242, 132, 42];
    if (f === 0) {
      c.px(cx, cy, white);
      c.px(cx + dx, cy + dy, white);
    }
    for (const k of [-1, 0, 1]) {
      const ang = Math.atan2(dy, dx) + k * 0.65;
      const r1 = 1.5 + f * 1.4;
      const r2 = 2.8 + f * 1.6;
      c.px(cx + Math.cos(ang) * r1, cy + Math.sin(ang) * r1, f === 0 ? white : yellow);
      c.px(cx + Math.cos(ang) * r2, cy + Math.sin(ang) * r2, f === 2 ? orange : yellow);
    }
  }

  c.outline();
  return { width: size, height: size, data: c.data };
}

/**
 * 아군 6종(RIFLE, GATLING, SNIPER, EXECUTIONER, MORTAR, MLRS) 및
 * 적 4종(SPORE, SPIKE, PRISM, ROYAL) 투사체 전용 16x16 8방향 2프레임 픽셀 스프라이트.
 */
export function renderProjectilePixels(
  visual: ProjectileVisual | EnemyShotVisual,
  dir: SpriteDir8,
  frame: number = 0
): { width: number; height: number; data: Uint8ClampedArray } {
  const size = 16;
  const f = Math.abs(Math.round(frame)) % 2;
  const c = makePixelCanvas(size);
  const { dx, dy } = dir8Vector(dir);
  const perpX = -dy;
  const perpY = dx;
  const cx = 7.5;
  const cy = 7.5;
  const white: Rgb = [255, 255, 255];

  switch (visual) {
    case 'MORTAR':
    case 'MLRS': {
      const isMlrs = visual === 'MLRS';
      const bodyDark: Rgb = isMlrs ? [142, 34, 42] : [72, 82, 98];
      const bodyMid: Rgb = isMlrs ? [224, 68, 64] : [122, 134, 152];
      const tipCol: Rgb = isMlrs ? [255, 214, 84] : [242, 142, 38];
      const flame1: Rgb = isMlrs ? [110, 238, 255] : [255, 196, 72];
      const flame2: Rgb = isMlrs ? [255, 207, 74] : [224, 92, 32];

      // 후방 추진 화염 + 연기 퍼프
      for (let t = 2; t <= 5; t += 1) {
        const tx = cx - dx * t;
        const ty = cy - dy * t;
        c.px(tx, ty, t === 2 ? white : t === 3 ? flame1 : flame2);
        if (t === 3 + f) {
          c.px(tx + perpX, ty + perpY, flame2);
          c.px(tx - perpX, ty - perpY, flame2);
        }
      }
      // 방향성 포탄/로켓 동체
      for (let s = -1; s <= 2; s += 1) {
        const bx = cx + dx * s;
        const by = cy + dy * s;
        const col = s === 2 ? white : s === 1 ? tipCol : bodyMid;
        c.px(bx, by, col);
        if (s <= 1) {
          c.px(bx + perpX, by + perpY, bodyMid);
          c.px(bx - perpX, by - perpY, bodyDark);
        }
      }
      break;
    }

    case 'SNIPER':
    case 'EXECUTIONER': {
      const isExec = visual === 'EXECUTIONER';
      const trail: Rgb = isExec ? [255, 56, 88] : [255, 196, 72];
      const sub: Rgb = isExec ? [255, 207, 74] : [110, 224, 255];
      // 장거리 고속 철갑/레일건 창 탄두
      for (let s = -5; s <= 4; s += 1) {
        const px = cx + dx * s;
        const py = cy + dy * s;
        c.px(px, py, s >= 1 ? white : s >= -2 ? sub : trail);
        if (s >= -1 && s <= 1) {
          c.px(px + perpX, py + perpY, s === 0 ? white : trail);
          c.px(px - perpX, py - perpY, s === 0 ? white : trail);
        }
      }
      if (isExec && f === 0) {
        c.px(cx - dx * 2 + perpX * 2, cy - dy * 2 + perpY * 2, sub);
        c.px(cx - dx * 2 - perpX * 2, cy - dy * 2 - perpY * 2, sub);
      }
      break;
    }

    case 'GATLING': {
      // 개틀링 진화: 황금 듀얼 회전 예광탄
      const gold: Rgb = [255, 207, 74];
      const bright: Rgb = [255, 246, 172];
      for (const side of [-1, 1]) {
        const shift = side * (f === 0 ? 1 : -1);
        for (let s = -3; s <= 2; s += 1) {
          const px = cx + dx * (s + shift * 0.5) + perpX * side * 1.1;
          const py = cy + dy * (s + shift * 0.5) + perpY * side * 1.1;
          c.px(px, py, s >= 1 ? white : s >= -1 ? bright : gold);
        }
      }
      break;
    }

    case 'RIFLE': {
      // 기본 가우스 소총탄
      const gold: Rgb = [242, 193, 78];
      const orange: Rgb = [224, 122, 36];
      for (let s = -3; s <= 2; s += 1) {
        c.px(cx + dx * s, cy + dy * s, s >= 1 ? white : s >= -1 ? gold : orange);
      }
      c.px(cx + perpX, cy + perpY, gold);
      c.px(cx - perpX, cy - perpY, gold);
      break;
    }

    case 'SPIKE': {
      // 군체 가시투척충: 뼈색·산성 골침 가시
      const bone: Rgb = [238, 232, 212];
      const acid: Rgb = [168, 232, 56];
      const dark: Rgb = [112, 98, 82];
      for (let s = -3; s <= 3; s += 1) {
        c.px(cx + dx * s, cy + dy * s, s >= 2 ? white : s >= 0 ? bone : acid);
        if (s === -1 || s === 0) {
          c.px(cx + dx * s + perpX, cy + dy * s + perpY, bone);
          c.px(cx + dx * s - perpX, cy + dy * s - perpY, dark);
        }
      }
      break;
    }

    case 'PRISM': {
      // 교단 프리즘 포대: 청록·황금 회전 다이아몬드 광자탄
      const cyan: Rgb = [95, 224, 255];
      const deep: Rgb = [28, 124, 196];
      const gold: Rgb = [232, 196, 88];
      c.disc(cx, cy, 2.4, deep);
      c.px(cx, cy, white);
      for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
        c.px(cx + ox, cy + oy, cyan);
        c.px(cx + ox * 2, cy + oy * 2, f === 0 ? cyan : gold);
      }
      break;
    }

    case 'ROYAL': {
      // 보스(모체 / 대주교) 대형 황금·진홍 코어 탄막 구체
      const gold: Rgb = [255, 212, 72];
      const crimson: Rgb = [212, 42, 68];
      c.disc(cx, cy, 3.2, crimson);
      c.disc(cx - 0.3, cy - 0.3, 2.1, gold);
      c.px(cx - 1, cy - 1, white);
      c.px(cx, cy, white);
      if (f === 1) {
        for (const [ox, oy] of [[-3, 0], [3, 0], [0, -3], [0, 3]] as const) {
          c.px(cx + ox, cy + oy, gold);
        }
      }
      break;
    }

    case 'SPORE':
    default: {
      // 포자충 / 포자 탑: 산성 포자 구체 + 뒤따르는 기포 도트
      const acidBright: Rgb = [224, 252, 120];
      const acidMid: Rgb = [148, 216, 48];
      const acidDark: Rgb = [68, 128, 24];
      c.disc(cx, cy, 2.5, acidDark);
      c.disc(cx - 0.4, cy - 0.4, 1.8, acidMid);
      c.px(cx - 1, cy - 1, white);
      c.px(cx, cy - 1, acidBright);
      // 후방 기포
      c.px(cx - dx * (3 + f), cy - dy * (3 + f), acidBright);
      c.px(cx - dx * 4 + perpX * (f === 0 ? 1 : -1), cy - dy * 4 + perpY * (f === 0 ? 1 : -1), acidMid);
      break;
    }
  }

  c.outline();
  return { width: size, height: size, data: c.data };
}

